// LeakStop: the hooks module. Every use of `$` lives in this file; detection,
// masking, policy, command analysis and messages are pure modules that never
// receive it.
//
// Rules this file keeps:
// - Every `$` call is spelled in full, and event names are string literals.
// - A hook that can deny has a `.catch` that denies (monitor mode: lets it go).
// - Nothing that holds a secret is stored, logged or shown: findings are turned
//   into MaskedFindings first, and only those cross into `$`.
// - It never approves a call on its own: `next(e)` after a pass leaves the
//   user's permissions and rules in force.

import type { EngineInterface, Register, ToolCallInput } from 'claude-code'

import type { Decision, StoredConfig, StoredFinding } from '../types'
import { analyzeCommand } from './commands.ts'
import { EMPTY_CONFIG, matchesAny, parseConfig, toRule } from './config.ts'
import type { CommandFacts, GitOp } from './commands.ts'
import { classifyPath, scanEdit, scanText, scanWrite } from './detect.ts'
import type { Finding, Rule, ScanResult } from './detect.ts'
import { scanDiff } from './diff.ts'
import type { DiffFinding } from './diff.ts'
import { describe, fingerprint, mask, redact } from './mask.ts'
import type { MaskedFinding } from './mask.ts'
import * as say from './messages.ts'
import type { WriteTool } from './messages.ts'
import { MAX_READ, collect, isLikelyBinary, toolLabel } from './outbound.ts'
import { decide, decideAll } from './policy.ts'
import type { Action, Destination, Mode } from './policy.ts'
import { USAGE, allowedText, bannerLine, fit, historyRows, mergeAllowed, parseArgs, resolveIds, summaryText } from './ui.ts'

const { USE_ENV, ALLOW_ONCE, CANCEL, SHOW_NAMES, ADD_GITIGNORE } = say

const MAX_FINDINGS = 100
const MAX_ALLOW_ONCE = 500
const MAX_UNTRACKED_READ = 200
const GIT_TIMEOUT_MS = 20000

const findingsRef = { plugin: 'leakstop', key: 'findings' } as const
const allowOnceRef = { plugin: 'leakstop', key: 'allowOnce' } as const
const pausedRef = { plugin: 'leakstop', key: 'paused' } as const
const bannerRef = { plugin: 'leakstop', key: 'banner' } as const
const configRef = { plugin: 'leakstop', key: 'config' } as const

/** The senders of a prompt that are not the user at the keyboard. */
const AUTOMATED: ReadonlySet<string> = new Set(['task-notification', 'scheduled-trigger', 'peer', 'peer-send-message', 'projects-relay', 'channel', 'coordinator', 'observer', 'observer-activity', 'slack-ping', 'plugin'])

const PANE = 'leakstop'
const MAX_BANNER = 5
const MAX_ALLOWED_FOREVER = 1000

/** What is kept about a finding or a sensitive operation: never a value. */
type Note = Pick<MaskedFinding, 'fingerprint' | 'ruleId' | 'label' | 'severity' | 'line'> & { path?: string }

/** The outcome of a check: nothing to say, a denial, or a rewritten command. */
type Verdict = { deny: string } | { command: string } | undefined

// --- Helpers that take `$` (top-level functions of this file) ---------------

/** True when git ignores `path`. Anything unexpected (not a repo, no git) reads as "not ignored". */
async function isIgnored($: EngineInterface, path: string): Promise<boolean> {
  try {
    const result = await $.process.run(['git', 'check-ignore', '-q', '--', path], { timeoutMs: 5000 })
    return result.exitCode === 0
  } catch {
    return false
  }
}

async function sessionCwd($: EngineInterface): Promise<string | undefined> {
  try {
    return await $.session.cwd()
  } catch {
    return undefined
  }
}

/** Line of `oldString` in the file on disk, so an Edit's findings point at real lines. 0 when unknown. */
async function lineOffset($: EngineInterface, path: string, oldString: string): Promise<number> {
  if (oldString === '') return 0
  try {
    const content = await $.fs.read(path)
    if (typeof content !== 'string') return 0
    const index = content.indexOf(oldString)
    if (index < 0) return 0
    let lines = 0
    for (let i = 0; i < index; i++) if (content.charCodeAt(i) === 10) lines++
    return lines
  } catch {
    return 0
  }
}

async function record($: EngineInterface, tool: string, path: string, notes: readonly Note[], decision: Decision): Promise<void> {
  const at = await $.clock.now()
  const entries: StoredFinding[] = notes.map((n) => ({
    fingerprint: n.fingerprint,
    ruleId: n.ruleId,
    label: n.label,
    severity: n.severity,
    path: n.path ?? path,
    line: n.line,
    tool,
    decision,
    at,
  }))
  const { value = [] } = await $.state.get(findingsRef)
  await $.state.set(findingsRef, [...value, ...entries].slice(-MAX_FINDINGS))
  if (decision === 'warned' || decision === 'masked') {
    const { value: banner = [] } = await $.state.get(bannerRef)
    await $.state.set(bannerRef, [...banner, ...entries].slice(-MAX_BANNER))
  }
}

/** True where a banner can be drawn: the terminal and the desktop app. The VS Code panel and `claude -p` draw nothing. */
async function drawsBanner($: EngineInterface): Promise<boolean> {
  try {
    const surfaces = await $.session.surfaces()
    return surfaces.some((surface) => surface === 'terminal' || surface === 'desktop')
  } catch {
    return false
  }
}

async function clearBanner($: EngineInterface): Promise<void> {
  const { value = [] } = await $.state.get(bannerRef)
  if (value.length > 0) await $.state.set(bannerRef, [])
}

async function setPaused($: EngineInterface, paused: boolean, hasStatus: boolean): Promise<void> {
  await $.state.set(pausedRef, paused)
  if (hasStatus) showStatus($, paused)
}

/** The line under the prompt that says LeakStop is on: when it is missing, nothing is protecting the session. */
function showStatus($: EngineInterface, paused: boolean): void {
  $.ui.status(paused ? '△ LeakStop paused · /leakstop resume' : '◆ LeakStop on')
}

/** Allows findings for good: the store is shared by every session on the machine. */
async function allowForever($: EngineInterface, fingerprints: readonly string[]): Promise<void> {
  const stored = await $.store.get('allowFingerprints')
  const current = Array.isArray(stored) ? stored.filter((x): x is string => typeof x === 'string') : []
  await $.store.set('allowFingerprints', [...new Set([...current, ...fingerprints])].slice(-MAX_ALLOWED_FOREVER))
}

async function rememberAllowOnce($: EngineInterface, fingerprints: readonly string[]): Promise<void> {
  const { value = [] } = await $.state.get(allowOnceRef)
  await $.state.set(allowOnceRef, [...new Set([...value, ...fingerprints])].slice(-MAX_ALLOW_ONCE))
}

/** Reads the project's `.leakstop.json` (at session start and on `/leakstop reload`). A missing file is not a problem; a bad one is reported and the defaults apply. */
async function loadConfig($: EngineInterface): Promise<StoredConfig> {
  let config: StoredConfig = EMPTY_CONFIG
  let exists = false
  try {
    exists = await $.fs.exists('.leakstop.json')
  } catch {
    exists = false
  }
  if (exists) {
    try {
      const content = await $.fs.read('.leakstop.json')
      config = typeof content === 'string' ? parseConfig(content) : { ...EMPTY_CONFIG, warnings: ['.leakstop.json could not be read as text, so the defaults apply'] }
    } catch {
      config = { ...EMPTY_CONFIG, warnings: ['.leakstop.json could not be read (is it over 4 MiB?), so the defaults apply'] }
    }
  }
  await $.state.set(configRef, config)
  return config
}

async function getConfig($: EngineInterface): Promise<StoredConfig> {
  const { value } = await $.state.get(configRef)
  return value ?? EMPTY_CONFIG
}

/** The project's custom rules, compiled. */
const customRules = (config: StoredConfig): Rule[] => config.customRules.map(toRule).filter((rule): rule is Rule => rule !== undefined)

/** Medium findings in a path the project told us to ignore are dropped; critical ones never are. */
const isRelaxed = (config: StoredConfig, severity: string, path: string): boolean => severity === 'medium' && matchesAny(path, config.ignorePaths)

/** What is allowed, by where it came from: this session, the user for good (the machine-wide store) and the project. */
async function allowedSources($: EngineInterface, config: StoredConfig): Promise<{ session: string[]; forever: string[]; project: string[] }> {
  const { value: session = [] } = await $.state.get(allowOnceRef)
  let stored: unknown
  try {
    stored = await $.store.get('allowFingerprints')
  } catch {
    stored = undefined
  }
  const forever = Array.isArray(stored) ? stored.filter((x): x is string => typeof x === 'string') : []
  return { session, forever, project: config.allowFingerprints }
}

/** Fingerprints allowed for this session, the ones the user allowed for good and the ones the project allows. */
async function allowedFingerprints($: EngineInterface, config: StoredConfig): Promise<Set<string>> {
  const { session, forever, project } = await allowedSources($, config)
  return new Set([...session, ...forever, ...project])
}

/** Stops allowing `fingerprints` (every one of the user's when `undefined`); the project's own list is not touched. Returns what was removed. */
async function forgetAllowed($: EngineInterface, fingerprints: readonly string[] | undefined): Promise<{ session: string[]; forever: string[] }> {
  const { session, forever } = await allowedSources($, EMPTY_CONFIG)
  const drop = (list: readonly string[]): string[] => (fingerprints === undefined ? [...list] : list.filter((f) => fingerprints.includes(f)))
  const removed = { session: drop(session), forever: drop(forever) }
  if (removed.session.length > 0) await $.state.set(allowOnceRef, session.filter((f) => !removed.session.includes(f)))
  if (removed.forever.length > 0) {
    const kept = forever.filter((f) => !removed.forever.includes(f))
    if (kept.length > 0) await $.store.set('allowFingerprints', kept)
    else await $.store.delete('allowFingerprints')
  }
  return removed
}

/** True when VS Code is the only place the session draws: its dialog runs the lines of a question together. */
async function isVsCodeOnly($: EngineInterface): Promise<boolean> {
  try {
    const surfaces = await $.session.surfaces()
    return surfaces.includes('vscode') && !surfaces.some((surface) => surface === 'terminal' || surface === 'desktop')
  } catch {
    return false
  }
}

/** The user's answer, or `undefined` when nobody could answer (dismissed, `claude -p`, no interface). */
async function askUser($: EngineInterface, question: string, options: readonly string[]): Promise<string | undefined> {
  try {
    return await $.ui.ask((await isVsCodeOnly($)) ? say.flatten(question) : question, { options, header: 'LeakStop' })
  } catch {
    return undefined
  }
}

type Spec = {
  action: Action
  tool: string
  path: string
  notes: readonly Note[]
  question: string
  options: readonly string[]
  deny: string
  /** Transcript lines for a warning. */
  warn: readonly string[]
  /** The command to run instead when the user picks "Show names only". */
  rewrite?: string
}

/** Carries out the policy's action: pass, warn, hold (ask) or block. `undefined` means the call may go on. */
async function settle($: EngineInterface, spec: Spec): Promise<Verdict> {
  switch (spec.action) {
    case 'pass':
      await record($, spec.tool, spec.path, spec.notes, 'passed')
      return undefined
    case 'warn':
      // Where a banner is drawn it says it; where nothing is drawn, the transcript does.
      if (!(await drawsBanner($))) for (const line of spec.warn) $.ui.log(line)
      await record($, spec.tool, spec.path, spec.notes, 'warned')
      return undefined
    case 'hold': {
      const answer = await askUser($, spec.question, spec.options)
      if (answer === ALLOW_ONCE) {
        await rememberAllowOnce($, spec.notes.map((n) => n.fingerprint))
        await record($, spec.tool, spec.path, spec.notes, 'allowed')
        return undefined
      }
      if (answer === SHOW_NAMES && spec.rewrite !== undefined) {
        await record($, spec.tool, spec.path, spec.notes, 'allowed')
        return { command: spec.rewrite }
      }
      await record($, spec.tool, spec.path, spec.notes, 'denied')
      return { deny: `${say.answerNote(answer)} ${spec.deny}` }
    }
    case 'block':
      await record($, spec.tool, spec.path, spec.notes, 'denied')
      return { deny: spec.deny }
  }
}

/** A sensitive operation (no secret value to fingerprint) as a Note, identified by what it is about. */
async function operation(ruleId: string, label: string, about: string): Promise<Note> {
  return { fingerprint: await fingerprint(about), ruleId, label, severity: 'critical', line: 0 }
}

/** Editing LeakStop's own configuration is always held: otherwise Claude could allowlist its own findings. */
async function checkConfig($: EngineInterface, tool: string, shownPath: string, mode: Mode): Promise<Verdict> {
  if (decide('config-edit', 'critical', mode) !== 'hold') {
    $.ui.log(say.noticeLine(`the change to ${shownPath} would have been held`, false))
    return undefined
  }
  const answer = await askUser($, say.configQuestion(shownPath), [ALLOW_ONCE, CANCEL])
  if (answer === ALLOW_ONCE) return undefined
  await record($, tool, shownPath, [await operation('config-edit', 'LeakStop configuration change', `config:${shownPath}`)], 'denied')
  return { deny: `${say.answerNote(answer)} ${say.configDenyMessage(shownPath)}` }
}

/** True when the file is sensitive by path and, for `.npmrc` and `.pypirc`, holds a token. */
async function isSensitiveFile($: EngineInterface, path: string, dir?: string): Promise<boolean> {
  const kind = classifyPath(path)
  if (kind === undefined) return false
  if (!kind.requiresToken) return true
  try {
    const content = await $.fs.read(dir === undefined || path.startsWith('/') ? path : `${dir}/${path}`)
    return typeof content === 'string' && scanText(content, { path }).findings.length > 0
  } catch {
    return false
  }
}

async function git($: EngineInterface, args: readonly string[], dir?: string): Promise<{ isOk: boolean; stdout: string; isTruncated: boolean }> {
  const init = dir === undefined ? { timeoutMs: GIT_TIMEOUT_MS } : { cwd: dir, timeoutMs: GIT_TIMEOUT_MS }
  const result = await $.process.run(['git', ...args], init)
  return { isOk: result.exitCode === 0, stdout: result.stdout, isTruncated: result.isStdoutTruncated }
}

const names = (output: string): string[] => output.split('\0').filter((name) => name !== '')

const normalize = (path: string): string => path.replace(/^\.\//, '').replace(/\/+$/, '')

const isInScope = (file: string, paths: readonly string[]): boolean => paths.some((p) => file === normalize(p) || file.startsWith(`${normalize(p)}/`))

// --- Bash checks -------------------------------------------------------------

/** A literal secret inside the command: a `curl` header, an `export`, a `--build-arg`, a heredoc. */
async function checkSecrets($: EngineInterface, command: string, mode: Mode, allowed: ReadonlySet<string>, config: StoredConfig, writeTargets?: readonly string[]): Promise<Verdict> {
  const scan = scanText(command, { extraRules: customRules(config) })
  if (scan.isPartial) $.ui.log('LeakStop: the custom rules were too slow and did not cover the whole command')
  const found = scan.findings
  if (found.length === 0) return undefined
  const masked = (await Promise.all(found.map(describe))).filter((f) => !allowed.has(f.fingerprint))
  if (masked.length === 0) return undefined
  // `cat > .env <<EOF … EOF` or `echo KEY=… >> .env` into files git ignores is where a secret belongs.
  let destination: Destination = 'command'
  if (writeTargets !== undefined) {
    const ignored = await Promise.all(writeTargets.map((target) => isIgnored($, target)))
    if (ignored.every(Boolean)) destination = 'ignored-file'
  }
  const action = decideAll(destination, masked.map((f) => f.severity), mode)
  return settle($, {
    action,
    tool: 'Bash',
    path: '',
    notes: masked,
    question: say.commandSecretQuestion(masked),
    options: [USE_ENV, ALLOW_ONCE, CANCEL],
    deny: say.commandSecretDeny(masked),
    warn: masked.map((f) => say.noticeLine(`${f.severity.toUpperCase()} · ${f.label} in a command`, mode === 'monitor')),
  })
}

/** Printing sensitive files, the whole environment or a secret variable into the conversation. */
async function checkSensitive($: EngineInterface, facts: CommandFacts, mode: Mode, allowed: ReadonlySet<string>): Promise<Verdict> {
  const action = decide('sensitive-dump', 'critical', mode)
  let command: string | undefined

  const files: string[] = []
  for (const file of facts.readFiles) if (await isSensitiveFile($, file)) files.push(file)
  const fileNotes = await Promise.all(files.map((file) => operation('sensitive-file-read', 'Sensitive file printed', `path:${file}`)))
  const pendingFiles = files.filter((_, i) => !allowed.has((fileNotes[i] as Note).fingerprint))
  if (pendingFiles.length > 0) {
    const notes = fileNotes.filter((n) => !allowed.has(n.fingerprint))
    const verdict = await settle($, {
      action,
      tool: 'Bash',
      path: pendingFiles.join(', '),
      notes,
      question: say.dumpQuestion('This command would print files that hold secrets', pendingFiles),
      options: facts.namesOnly === undefined ? [ALLOW_ONCE, CANCEL] : [SHOW_NAMES, ALLOW_ONCE, CANCEL],
      deny: say.fileReadDeny(pendingFiles),
      warn: [say.noticeLine(`${pendingFiles.join(', ')} would be printed`, mode === 'monitor')],
      rewrite: facts.namesOnly,
    })
    if (verdict !== undefined && 'deny' in verdict) return verdict
    if (verdict !== undefined) command = verdict.command
  }

  if (facts.isEnvDump) {
    const note = await operation('environment-dump', 'Environment printed', 'env-dump')
    if (!allowed.has(note.fingerprint)) {
      const verdict = await settle($, {
        action,
        tool: 'Bash',
        path: 'environment',
        notes: [note],
        question: say.dumpQuestion('This command would print the whole environment', ['printenv / env']),
        options: facts.namesOnly === undefined ? [ALLOW_ONCE, CANCEL] : [SHOW_NAMES, ALLOW_ONCE, CANCEL],
        deny: say.ENV_DUMP_DENY,
        warn: [say.noticeLine('the whole environment would be printed', mode === 'monitor')],
        rewrite: facts.namesOnly,
      })
      if (verdict !== undefined && 'deny' in verdict) return verdict
      if (verdict !== undefined) command = verdict.command
    }
  }

  if (facts.secretVars.length > 0) {
    const notes = await Promise.all(facts.secretVars.map((name) => operation('secret-variable-print', 'Secret variable printed', `env-var:${name}`)))
    const pending = facts.secretVars.filter((_, i) => !allowed.has((notes[i] as Note).fingerprint))
    if (pending.length > 0) {
      const verdict = await settle($, {
        action,
        tool: 'Bash',
        path: pending.join(', '),
        notes: notes.filter((n) => !allowed.has(n.fingerprint)),
        question: say.dumpQuestion('This command would print secret variables', pending),
        options: [ALLOW_ONCE, CANCEL],
        deny: say.secretVarDeny(pending),
        warn: [say.noticeLine(`${pending.join(', ')} would be printed`, mode === 'monitor')],
      })
      if (verdict !== undefined && 'deny' in verdict) return verdict
    }
  }

  return command === undefined ? undefined : { command }
}

/** Sensitive files a recursive search could reach, found by looking in the folders it was given. */
const FIND_SENSITIVE: readonly string[] = [
  '(',
  ...['.env', '.env.*', '*.env', '*.pem', '*.key', '*.p12', '*.pfx', 'id_rsa*', 'id_dsa*', 'id_ecdsa*', 'id_ed25519*', 'credentials.json', 'service-account*.json', '*.tfstate', '*.tfstate.backup'].flatMap((name, i) => (i === 0 ? ['-name', name] : ['-o', '-name', name])),
  ')',
  '-type',
  'f',
  '-not',
  '-path',
  '*/node_modules/*',
  '-not',
  '-path',
  '*/.git/*',
]

/** `grep -r KEY .` reads `.env` too: grep ignores .gitignore and hidden-file rules. Hold when a sensitive file is within reach. */
async function checkSearch($: EngineInterface, search: Search, mode: Mode, allowed: ReadonlySet<string>): Promise<Verdict> {
  const found: string[] = []
  for (const dir of search.dirs.slice(0, 5)) {
    try {
      const result = await $.process.run(['find', dir, '-maxdepth', '8', ...FIND_SENSITIVE], { timeoutMs: 5000 })
      for (const file of names(result.stdout.replace(/\n/g, '\0'))) found.push(file.replace(/^\.\//, ''))
    } catch {
      // A folder that cannot be listed (or takes too long) is not a reason to block the search.
    }
  }
  const candidates = [...new Set(found)]
    .filter((file) => classifyPath(file) !== undefined && classifyPath(file)?.requiresToken === false)
    .filter((file) => !matchesAny(file, search.excludes))
    .filter((file) => search.includes.length === 0 || matchesAny(file, search.includes))
    .slice(0, 20)
  // A search that honours .gitignore never opens the files git ignores (a plain .env).
  const reach: string[] = []
  for (const file of candidates) if (!(search.respectsIgnore && (await isIgnored($, file)))) reach.push(file)
  if (reach.length === 0) return undefined

  const note = await operation('sensitive-search', 'Search through sensitive files', `search:${[...reach].sort().join('\n')}`)
  if (allowed.has(note.fingerprint)) return undefined
  return settle($, {
    action: decide('sensitive-dump', 'critical', mode),
    tool: 'Bash',
    path: reach.join(', '),
    notes: [note],
    question: say.searchQuestion(reach),
    options: [ALLOW_ONCE, CANCEL],
    deny: say.searchDeny(reach),
    warn: [say.noticeLine(`a search would print lines from ${reach.join(', ')}`, mode === 'monitor')],
  })
}

/** `git add -A` or `.` (or a named path) that would stage sensitive files git does not ignore. */
async function checkGitAdd($: EngineInterface, op: Extract<GitOp, { kind: 'add' }>, mode: Mode, allowed: ReadonlySet<string>): Promise<Verdict> {
  const untracked = await git($, ['ls-files', '--others', '--exclude-standard', '-z'], op.dir)
  const modified = await git($, ['diff', '--name-only', '-z'], op.dir)
  if (!untracked.isOk && !modified.isOk) return undefined
  const candidates = [...new Set([...names(untracked.stdout), ...names(modified.stdout)])].filter((file) => op.isAll || isInScope(file, op.paths))

  const sensitive: string[] = []
  for (const file of candidates.slice(0, 1000)) if (await isSensitiveFile($, file, op.dir)) sensitive.push(file)
  if (sensitive.length === 0) return undefined

  const note = await operation('git-add-sensitive', 'Sensitive files staged', `git-add:${[...sensitive].sort().join('\n')}`)
  if (allowed.has(note.fingerprint)) return undefined
  return settle($, {
    action: decide('git-add', 'critical', mode),
    tool: 'Bash',
    path: sensitive.join(', '),
    notes: [note],
    question: say.gitAddQuestion(sensitive),
    options: [ADD_GITIGNORE, ALLOW_ONCE, CANCEL],
    deny: say.gitAddDeny(sensitive),
    warn: [say.noticeLine(`git add would stage ${sensitive.join(', ')}`, mode === 'monitor')],
  })
}

type Pending = { findings: DiffFinding[]; isTruncated: boolean }

/** What a commit is about to contain: the staged diff and, when the command stages first, the rest. */
async function pendingForCommit($: EngineInterface, op: Extract<GitOp, { kind: 'commit' }>, config: StoredConfig): Promise<Pending> {
  const cached = await git($, ['diff', '--cached', '--no-color', '-U0'], op.dir)
  if (!cached.isOk) return { findings: [], isTruncated: false }
  const diffs = [cached.stdout]
  let isTruncated = cached.isTruncated

  const stagesAll = op.staging.some((s) => s.isAll)
  const stagedPaths = op.staging.flatMap((s) => (s.isAll ? [] : s.paths))
  // `-a`, or a `git add` earlier in the same command, stages tracked changes that are not staged yet.
  if (op.isAll || stagesAll) {
    const unstaged = await git($, ['diff', '--no-color', '-U0'], op.dir)
    if (unstaged.isOk) diffs.push(unstaged.stdout)
    isTruncated ||= unstaged.isTruncated
  } else if (stagedPaths.length > 0) {
    const unstaged = await git($, ['diff', '--no-color', '-U0', '--', ...stagedPaths], op.dir)
    if (unstaged.isOk) diffs.push(unstaged.stdout)
    isTruncated ||= unstaged.isTruncated
  }

  const extraRules = customRules(config)
  const findings = scanDiff(diffs.join('\n'), extraRules).findings

  // New files that an earlier `git add` in the same command would stage.
  if (stagesAll || stagedPaths.length > 0) {
    const untracked = await git($, ['ls-files', '--others', '--exclude-standard', '-z'], op.dir)
    const files = names(untracked.stdout).filter((file) => stagesAll || isInScope(file, stagedPaths))
    for (const file of files.slice(0, MAX_UNTRACKED_READ)) {
      try {
        const content = await $.fs.read(op.dir === undefined ? file : `${op.dir}/${file}`)
        if (typeof content === 'string') for (const finding of scanText(content, { path: file, extraRules }).findings) findings.push({ ...finding, path: file })
      } catch {
        // Unreadable or over 4 MiB: skipped, as the spec says.
      }
    }
  }
  return { findings, isTruncated }
}

/** What a push is about to publish: the added lines of every commit no remote has. */
async function pendingForPush($: EngineInterface, op: Extract<GitOp, { kind: 'push' }>, config: StoredConfig): Promise<Pending> {
  const log = await git($, ['log', '-p', '--no-color', '--format=', 'HEAD', '--not', '--remotes'], op.dir)
  if (!log.isOk) return { findings: [], isTruncated: false }
  return { findings: scanDiff(log.stdout, customRules(config)).findings, isTruncated: log.isTruncated }
}

/** Secrets in what is about to be committed or pushed: blocked without asking. */
async function checkPublish($: EngineInterface, kind: 'commit' | 'push', pending: Pending, mode: Mode, allowed: ReadonlySet<string>, config: StoredConfig): Promise<Verdict> {
  if (pending.isTruncated) $.ui.log('LeakStop: the diff is larger than 4 MiB, so only the first 4 MiB was scanned')
  if (pending.findings.length === 0) return undefined
  const described = await Promise.all(pending.findings.map(async (f) => ({ ...(await describe(f)), path: f.path })))
  const masked = described.filter((f) => !allowed.has(f.fingerprint) && !isRelaxed(config, f.severity, f.path))
  if (masked.length === 0) return undefined
  const destination: Destination = kind === 'commit' ? 'git-commit' : 'git-push'
  return settle($, {
    action: decideAll(destination, masked.map((f) => f.severity), mode),
    tool: 'Bash',
    path: '',
    notes: masked,
    question: '',
    options: [],
    deny: say.gitBlockMessage(kind, masked),
    warn: masked.map((f) => say.noticeLine(`${f.severity.toUpperCase()} · ${f.label} in ${f.path}:${f.line} (git ${kind})`, mode === 'monitor')),
  })
}

async function checkGit($: EngineInterface, op: GitOp, mode: Mode, allowed: ReadonlySet<string>, config: StoredConfig): Promise<Verdict> {
  if (op.kind === 'add') return checkGitAdd($, op, mode, allowed)
  if (op.kind === 'commit') return checkPublish($, 'commit', await pendingForCommit($, op, config), mode, allowed, config)
  return checkPublish($, 'push', await pendingForPush($, op, config), mode, allowed, config)
}

// --- Outbound tools ------------------------------------------------------------

/** Secrets in what a tool sends away: the web, another agent or session, a published page, an MCP server. */
async function guardOutbound($: EngineInterface, e: ToolCallInput, mode: Mode): Promise<Verdict> {
  const { value: paused = false } = await $.state.get(pausedRef)
  if (paused) return undefined

  const tool = e.tool
  const label = toolLabel(tool)
  const config = await getConfig($)
  const allowed = await allowedFingerprints($, config)
  const rules = customRules(config)
  const out = collect(e as unknown as Record<string, unknown>)
  if (out.isTruncated) $.ui.log(`LeakStop: ${label} carries more than LeakStop reads, so only part of it was scanned`)
  const cwd = await sessionCwd($)

  // An argument's name comes from the model and can itself be a secret: never show one that matches a rule.
  const place = (field: string): string => (scanText(field, { extraRules: rules }).findings.length > 0 ? '[argument]' : field)

  const found: (Finding & { path: string })[] = []
  for (const part of out.texts) {
    const where = place(part.field)
    const scan = scanText(part.text, { extraRules: rules })
    if (scan.isSkipped) $.ui.log(`LeakStop: ${label} ${where} is larger than 4 MiB and was not scanned`)
    if (scan.isPartial) $.ui.log(`LeakStop: the custom rules were too slow and did not cover ${label} ${where}`)
    // The place is the argument, not a line: it is not a file.
    for (const finding of scan.findings) found.push({ ...finding, line: 0, path: `${label} › ${where}` })
  }

  // Files the call sends: sensitive ones are held as they are, the rest are read and scanned.
  const sensitive: string[] = []
  let opened = 0
  for (const file of out.files) {
    if (await isSensitiveFile($, file)) {
      sensitive.push(file)
      continue
    }
    if (isLikelyBinary(file)) continue
    // Past the limit a file is still checked by its name, just not opened.
    if (opened >= MAX_READ) {
      if (opened++ === MAX_READ) $.ui.log(`LeakStop: ${label} sends more than ${MAX_READ} files, so only the first ${MAX_READ} were read`)
      continue
    }
    opened++
    try {
      const content = await $.fs.read(file)
      if (typeof content !== 'string') continue
      const shown = displayPathOf(file, cwd)
      const scan = scanText(content, { path: file, extraRules: rules })
      if (scan.isSkipped) $.ui.log(`LeakStop: ${shown} is larger than 4 MiB and was not scanned`)
      for (const finding of scan.findings) found.push({ ...finding, path: shown })
    } catch {
      // Unreadable or over 4 MiB: it cannot be checked, and the tool will say if it cannot read it either.
    }
  }

  const fileNotes = await Promise.all(sensitive.map((file) => operation('sensitive-file-send', 'Sensitive file sent', `path:${file}`)))
  const pendingFiles = sensitive.filter((_, i) => !allowed.has((fileNotes[i] as Note).fingerprint)).map((file) => displayPathOf(file, cwd))
  if (pendingFiles.length > 0) {
    const verdict = await settle($, {
      action: decide('sensitive-dump', 'critical', mode),
      tool,
      path: pendingFiles.join(', '),
      notes: fileNotes.filter((n) => !allowed.has(n.fingerprint)),
      question: say.outboundFileQuestion(tool, pendingFiles),
      options: [ALLOW_ONCE, CANCEL],
      deny: say.outboundFileDeny(tool, pendingFiles),
      warn: [say.noticeLine(`${label} would send ${pendingFiles.join(', ')}`, mode === 'monitor')],
    })
    if (verdict !== undefined && 'deny' in verdict) return verdict
  }

  if (found.length === 0) return undefined
  const described = await Promise.all(found.map(async (f) => ({ ...(await describe(f)), path: f.path })))
  const masked = described.filter((f) => !allowed.has(f.fingerprint) && !isRelaxed(config, f.severity, f.path))
  if (masked.length === 0) return undefined
  return settle($, {
    action: decideAll('outbound', masked.map((f) => f.severity), mode),
    tool,
    path: '',
    notes: masked,
    question: say.outboundQuestion(tool, masked),
    options: [ALLOW_ONCE, CANCEL],
    deny: say.outboundDeny(tool, masked),
    warn: masked.map((f) => say.noticeLine(`${f.severity.toUpperCase()} · ${f.label} in ${f.path}`, mode === 'monitor')),
  })
}

// --- Pure helpers of this file (no `$`) -------------------------------------

type Call = { tool: WriteTool; path: string; result: ScanResult; oldString?: string }

/** What the write is about to put on disk, scanned. `undefined`: nothing is written. */
function scanCall(e: ToolCallInput, extraRules: readonly Rule[]): Call | undefined {
  switch (e.tool) {
    case 'Write':
      return { tool: 'Write', path: e.file_path, result: scanWrite(e.file_path, e.content, { extraRules }) }
    case 'Edit':
      return { tool: 'Edit', path: e.file_path, result: scanEdit(e.file_path, e.old_string, e.new_string, { extraRules }), oldString: e.old_string }
    case 'NotebookEdit':
      return typeof e.new_source === 'string'
        ? { tool: 'NotebookEdit', path: e.notebook_path, result: scanText(e.new_source, { path: e.notebook_path, extraRules }) }
        : undefined
    default:
      return undefined
  }
}

const isConfigPath = (path: string): boolean => (path.split(/[\\/]/).pop() ?? '') === '.leakstop.json'

type Failure = { called: boolean; error: { kind: string } }

/** Fail closed: a hook that throws or runs out of time is skipped and the call would go on. Monitor mode never blocks. */
function onFailure(mode: Mode, next: Failure): { deny: string } | undefined {
  if (mode === 'monitor' || next.called) return undefined
  return { deny: `LeakStop could not check this call (${next.error.kind}), so it was blocked. Try again, or ask the user to review it.` }
}

// --- Tool output ---------------------------------------------------------------

/** Severities masked out of what a tool returns; monitor mode only reports them. */
const outputSeverities = (mode: Mode): ReadonlySet<string> => new Set(mode === 'strict' ? ['critical', 'medium'] : ['critical'])

/** Keys of an MCP result that carry binary data (images, audio, blobs), not text. */
const BINARY_KEYS: ReadonlySet<string> = new Set(['data', 'blob'])

type OutputScan = {
  /** Masks the secrets in one piece of output; in monitor mode the text comes back as it was. */
  take: (text: string) => Promise<string>
  notes: Map<string, MaskedFinding>
  skipped: number
}

function outputScan(mode: Mode, allowed: ReadonlySet<string>, rules: readonly Rule[]): OutputScan {
  const severities = outputSeverities(mode)
  const scan: OutputScan = {
    notes: new Map(),
    skipped: 0,
    take: async (text) => {
      if (text === '') return text
      const result = scanText(text, { extraRules: rules })
      if (result.isSkipped) scan.skipped++
      const hits: Finding[] = []
      for (const finding of result.findings) {
        if (!severities.has(finding.severity)) continue
        const note = await describe(finding)
        if (allowed.has(note.fingerprint)) continue
        hits.push(finding)
        scan.notes.set(note.fingerprint, note)
      }
      return mode === 'monitor' || hits.length === 0 ? text : redact(text, hits)
    },
  }
  return scan
}

/** The secrets on disk at `path` whose masked form `content` would write in their place. */
async function maskedOverwrite($: EngineInterface, path: string, content: string): Promise<MaskedFinding[]> {
  let current: unknown
  try {
    current = await $.fs.read(path)
  } catch {
    return []
  }
  if (typeof current !== 'string') return []
  const lost: MaskedFinding[] = []
  for (const finding of scanText(current).findings) {
    if (content.includes(mask(finding.value, finding.prefix)) && !content.includes(finding.value)) lost.push(await describe(finding))
  }
  return lost
}

/**
 * True for the file Claude Code saves a large output to: a regular file directly inside a
 * `tool-results` folder. Any other path a result names is never rewritten.
 */
async function isSavedOutput($: EngineInterface, path: string): Promise<boolean> {
  if (!/[\\/]tool-results[\\/][^\\/]+$/.test(path)) return false
  const stat = await $.fs.stat(path)
  return stat.kind === 'file' && stat.isLink !== true
}

/** Every string inside an MCP result, masked; binary fields are left alone. */
async function maskDeep(value: unknown, take: (text: string) => Promise<string>, depth = 0): Promise<unknown> {
  if (typeof value === 'string') return take(value)
  if (depth > 20 || value === null || typeof value !== 'object') return value
  if (Array.isArray(value)) {
    const out: unknown[] = []
    for (const item of value) out.push(await maskDeep(item, take, depth + 1))
    return out
  }
  const out: Record<string, unknown> = {}
  for (const [key, item] of Object.entries(value)) out[key] = BINARY_KEYS.has(key) ? item : await maskDeep(item, take, depth + 1)
  return out
}

/**
 * The tool's result with secrets masked, before the model or the transcript gets it. A large
 * Bash output is also saved whole to a file before any hook runs: that file is masked too.
 */
async function maskOutput($: EngineInterface, e: ToolCallInput, r: any, mode: Mode): Promise<any> {
  if (r === undefined || r.deny !== undefined || r.isError === true || r.result === null || typeof r.result !== 'object') return r
  const { value: paused = false } = await $.state.get(pausedRef)
  if (paused) return r
  const config = await getConfig($)
  const scan = outputScan(mode, await allowedFingerprints($, config), customRules(config))
  let result = r.result
  let path = ''

  if (e.tool === 'Bash') {
    result = { ...result, stdout: await scan.take(String(result.stdout ?? '')), stderr: await scan.take(String(result.stderr ?? '')) }
    if (typeof result.persistedOutputPath === 'string') {
      try {
        if (!(await isSavedOutput($, result.persistedOutputPath))) throw new Error('not a saved output')
        const saved = await $.fs.read(result.persistedOutputPath)
        if (typeof saved === 'string') {
          const masked = await scan.take(saved)
          if (masked !== saved) await $.fs.write(result.persistedOutputPath, masked)
        }
      } catch {
        $.ui.log('LeakStop: the saved output of this command could not be checked')
      }
    }
  } else if (e.tool === 'Read') {
    if (result.type !== 'text' || typeof result.file?.content !== 'string') return r
    path = displayPathOf(e.file_path, await sessionCwd($))
    result = { ...result, file: { ...result.file, content: await scan.take(result.file.content) } }
  } else {
    result = await maskDeep(result, scan.take)
  }

  if (scan.skipped > 0) $.ui.log(`LeakStop: an output of ${toolLabel(e.tool)} was larger than 4 MiB and was not checked`)
  const notes = [...scan.notes.values()]
  if (notes.length === 0) return r
  await record($, e.tool, path, notes, mode === 'monitor' ? 'warned' : 'masked')
  if (mode === 'monitor') return r
  return { result, context: [...(r.context ?? []), say.maskedContext(toolLabel(e.tool), notes)] }
}

// --- The module -------------------------------------------------------------

export const register: Register = (on, options) => {
  const mode: Mode = options.mode === 'monitor' || options.mode === 'strict' ? options.mode : 'standard'
  // Off by default: the line takes a row under the prompt in every session.
  const hasStatus = options.statusLine === true

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'leakstop', description: 'Show LeakStop findings, pause or resume protection, or allow a finding' })
    const config = await loadConfig($)
    for (const warning of config.warnings.slice(0, 5)) $.ui.log(`LeakStop: .leakstop.json: ${warning}`)
    if (hasStatus) {
      const { value: paused = false } = await $.state.get(pausedRef)
      showStatus($, paused)
    }
    return next(e)
  })

  // A warning stays above the prompt until the user's next message. A background agent finishing, a peer
  // session, a schedule or another plugin also submit prompts: they are not the user reading the warning.
  // The desktop app and VS Code may stamp the user's own message as `sdk` or `unclassified`, so what clears it
  // is anything that is not one of those automated senders.
  on('prompt.submit', async ($, e, next) => {
    if (!AUTOMATED.has(e.origin?.kind ?? '')) await clearBanner($)
    // A secret pasted into the message is masked before the model or the transcript gets it.
    // The prompt history (the up arrow) is the engine's and keeps what was typed.
    try {
      const { value: paused = false } = await $.state.get(pausedRef)
      if (paused) return next(e)
      const config = await getConfig($)
      const scan = outputScan(mode, await allowedFingerprints($, config), customRules(config))
      const text = await scan.take(e.text)
      const notes = [...scan.notes.values()]
      if (notes.length === 0) return next(e)
      await record($, 'prompt', 'your message', notes, mode === 'monitor' ? 'warned' : 'masked')
      if (mode === 'monitor') return next(e)
      return next({ ...e, text, context: [...(e.context ?? []), say.promptMaskedContext(notes)] })
    } catch {
      return next(e) // a prompt is never blocked
    }
  })

  on('command.run', { command: 'leakstop' }, async ($, e) => {
    const args = parseArgs(e.args)
    const { value: findings = [] } = await $.state.get(findingsRef)
    const { value: paused = false } = await $.state.get(pausedRef)
    const config = await getConfig($)

    if (args.kind === 'open') {
      await clearBanner($)
      let isPlaced = false
      try {
        isPlaced = (await $.ui.open({ id: PANE, title: 'LeakStop', focus: true })).isPlaced
      } catch {
        isPlaced = false
      }
      // Where nothing is drawn (the VS Code panel) a "placed" panel is invisible: say it in text.
      const isShown = isPlaced && (await drawsBanner($))
      return isShown ? {} : { text: summaryText(findings, paused, config.warnings) }
    }
    if (args.kind === 'usage') return { text: USAGE }
    if (args.kind === 'allowed') {
      const { session, forever, project } = await allowedSources($, config)
      return { text: allowedText(mergeAllowed(session, forever, project), findings) }
    }

    // Changing what LeakStop checks is the user's call. A command that did not
    // come from the person (a task, a peer session, another plugin) is refused.
    if (e.origin?.kind !== 'composer' && e.origin?.kind !== 'bridge') {
      return { text: `LeakStop: /leakstop ${args.kind} only works when you type it yourself.` }
    }
    if (args.kind === 'pause') {
      await setPaused($, true, hasStatus)
      return { text: 'LeakStop paused: nothing is checked until you run /leakstop resume. Changes to .leakstop.json are still held.' }
    }
    if (args.kind === 'resume') {
      await setPaused($, false, hasStatus)
      return { text: 'LeakStop resumed.' }
    }
    if (args.kind === 'reload') {
      const reloaded = await loadConfig($)
      const parts = [`${reloaded.customRules.length} custom rule${reloaded.customRules.length === 1 ? '' : 's'}`, `${reloaded.ignorePaths.length} ignored path${reloaded.ignorePaths.length === 1 ? '' : 's'}`, `${reloaded.allowFingerprints.length} allowed fingerprint${reloaded.allowFingerprints.length === 1 ? '' : 's'}`]
      const notes = reloaded.warnings.slice(0, 5).map((warning) => `.leakstop.json: ${warning}`)
      return { text: [`LeakStop reloaded .leakstop.json: ${parts.join(', ')}.`, ...notes].join('\n') }
    }
    if (args.kind === 'forget') {
      const isAll = args.ids.length === 1 && args.ids[0]?.toLowerCase() === 'all'
      const { fingerprints, unknown } = isAll ? { fingerprints: undefined, unknown: [] as string[] } : resolveIds(args.ids, findings)
      const removed = await forgetAllowed($, fingerprints)
      const count = new Set([...removed.session, ...removed.forever]).size
      const kept = (fingerprints ?? config.allowFingerprints).filter((f) => config.allowFingerprints.includes(f))
      const done = count > 0 ? `Stopped allowing ${count} finding${count === 1 ? '' : 's'}: ${[...new Set([...removed.session, ...removed.forever])].join(' ')}.` : 'Nothing of yours was allowed, so nothing changed.'
      const notes = [
        ...(kept.length > 0 ? [`Still allowed by .leakstop.json (edit that file to remove): ${kept.join(' ')}.`] : []),
        ...(unknown.length > 0 ? [`Not recognised: ${unknown.join(', ')}.`] : []),
      ]
      return { text: [done, ...notes, ...(unknown.length > 0 ? [USAGE] : [])].join('\n') }
    }
    const { fingerprints, unknown } = resolveIds(args.ids, findings)
    if (fingerprints.length > 0) await allowForever($, fingerprints)
    const done = fingerprints.length > 0 ? `Allowed for good: ${fingerprints.join(' ')}.` : 'Nothing was allowed.'
    return { text: unknown.length > 0 ? `${done} Not recognised: ${unknown.join(', ')}.\n${USAGE}` : done }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { value: banner = [] } = await $.state.get(bannerRef)
    const { value: paused = false } = await $.state.get(pausedRef)
    if (!paused && banner.length === 0) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box>
        <Text color={paused ? 'red' : 'yellow'}>{bannerLine(banner, paused, e.props.bodyColumns)}</Text>
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const { value: findings = [] } = await $.state.get(findingsRef)
    const { value: paused = false } = await $.state.get(pausedRef)
    const width = e.props.bodyColumns
    const room = Math.max(1, Math.floor(((e.viewport?.rows ?? 24) - 4) / 2))
    const rows = historyRows(findings, width).slice(0, room)

    return (
      <Box flexDirection="column">
        {paused && <Text color="red">{fit('PAUSED · nothing is being checked', width)}</Text>}
        {rows.length === 0 && <Text dimColor>No findings this session.</Text>}
        {rows.map((row) => (
          <Box flexDirection="column">
            <Text>{row.head}</Text>
            <Text dimColor>{row.detail}</Text>
          </Box>
        ))}
        <Box gap={2}>
          <Button key="pause" hotkey="1" label={paused ? 'Resume' : 'Pause'} onPress={() => setPaused($, !paused, hasStatus)} />
          <Button key="close" hotkey="2" label="Close" onPress={() => $.ui.close({ id: PANE })} />
        </Box>
      </Box>
    )
  })

  on('tool.call', { tool: ['Edit', 'Write', 'NotebookEdit'] }, async ($, e, next) => {
    // Claude saw the masked form of a secret this file holds: writing the file back from what it saw would replace the real value.
    if (e.tool === 'Write' && e.content.includes('••••••')) {
      const lost = await maskedOverwrite($, e.file_path, e.content)
      if (lost.length > 0) return { deny: say.maskedOverwriteDeny(displayPathOf(e.file_path, await sessionCwd($)), lost) }
    }
    const config = await getConfig($)
    const call = scanCall(e, customRules(config))
    if (call === undefined) return next(e)
    const cwd = await sessionCwd($)
    const shownPath = displayPathOf(call.path, cwd)

    // Self-protection comes first and holds even when LeakStop is paused.
    if (isConfigPath(call.path)) {
      const verdict = await checkConfig($, call.tool, shownPath, mode)
      return verdict === undefined ? next(e) : { deny: (verdict as { deny: string }).deny }
    }

    const { value: paused = false } = await $.state.get(pausedRef)
    if (paused) return next(e)

    if (call.result.isSkipped) {
      $.ui.log(`LeakStop: ${shownPath} is larger than 4 MiB and was not scanned`)
      return next(e)
    }
    if (call.result.isPartial) $.ui.log(`LeakStop: the custom rules were too slow and did not cover all of ${shownPath}`)
    if (call.result.findings.length === 0) return next(e)

    const offset = call.oldString === undefined ? 0 : await lineOffset($, call.path, call.oldString)
    const described = await Promise.all(call.result.findings.map(describe))
    const masked = described.map((f) => ({ ...f, line: f.line + offset })).filter((f) => !isRelaxed(config, f.severity, shownPath))
    if (masked.length === 0) return next(e)

    const allowed = await allowedFingerprints($, config)
    const pending = masked.filter((f) => !allowed.has(f.fingerprint))
    if (pending.length === 0) {
      await record($, call.tool, shownPath, masked, 'allowed')
      return next(e)
    }

    const destination: Destination = (await isIgnored($, call.path)) ? 'ignored-file' : 'file'
    const severities = pending.map((f) => f.severity)
    const wouldHold = mode === 'monitor' && decideAll(destination, severities, 'standard') === 'hold'
    const verdict = await settle($, {
      action: decideAll(destination, severities, mode),
      tool: call.tool,
      path: shownPath,
      notes: pending,
      question: say.holdQuestion(call.tool, shownPath, pending),
      options: [USE_ENV, ALLOW_ONCE, CANCEL],
      deny: say.denyMessage(call.tool, shownPath, pending),
      warn: pending.map((f) => say.warnLine(shownPath, f, wouldHold)),
    })
    return verdict === undefined ? next(e) : { deny: (verdict as { deny: string }).deny }
  }).catch(($, e, next) => onFailure(mode, next) ?? next(e))

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const facts = analyzeCommand(e.command)

    if (facts.touchesConfig) {
      const verdict = await checkConfig($, 'Bash', '.leakstop.json', mode)
      if (verdict !== undefined) return { deny: (verdict as { deny: string }).deny }
    }

    const { value: paused = false } = await $.state.get(pausedRef)
    if (paused) return next(e)

    const config = await getConfig($)
    const allowed = await allowedFingerprints($, config)
    let command = e.command

    const secrets = await checkSecrets($, e.command, mode, allowed, config, facts.writeTargets)
    if (secrets !== undefined && 'deny' in secrets) return secrets

    const sensitive = await checkSensitive($, facts, mode, allowed)
    if (sensitive !== undefined) {
      if ('deny' in sensitive) return sensitive
      command = sensitive.command
    }

    for (const search of facts.searches) {
      const verdict = await checkSearch($, search, mode, allowed)
      if (verdict !== undefined && 'deny' in verdict) return verdict
    }

    for (const op of facts.git) {
      const verdict = await checkGit($, op, mode, allowed, config)
      if (verdict !== undefined && 'deny' in verdict) return verdict
    }

    return command === e.command ? next(e) : next({ ...e, command })
  }).catch(($, e, next) => onFailure(mode, next) ?? next(e))

  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    if (!(await isSensitiveFile($, e.file_path))) return next(e)

    const { value: paused = false } = await $.state.get(pausedRef)
    if (paused) return next(e)

    const note = await operation('sensitive-file-read', 'Sensitive file read', `path:${e.file_path}`)
    const allowed = await allowedFingerprints($, await getConfig($))
    if (allowed.has(note.fingerprint)) return next(e)

    const cwd = await sessionCwd($)
    const shownPath = displayPathOf(e.file_path, cwd)
    const verdict = await settle($, {
      action: decide('read', 'critical', mode),
      tool: 'Read',
      path: shownPath,
      notes: [note],
      question: say.readQuestion(shownPath),
      options: [ALLOW_ONCE, CANCEL],
      deny: say.readDeny(shownPath, mode === 'strict'),
      warn: [say.noticeLine(`${shownPath} is a sensitive file`, mode === 'monitor')],
    })
    return verdict === undefined ? next(e) : { deny: (verdict as { deny: string }).deny }
  }).catch(($, e, next) => onFailure(mode, next) ?? next(e))

  // What leaves the session through a tool: a secret there cannot be taken back.
  on('tool.call', { tool: ['WebFetch', 'WebSearch', 'Agent', 'SendMessage', 'SendFile', 'Artifact', 'ArtifactData', 'ArtifactComments', 'PushNotification', 'SendFeedback', 'RemoteTrigger'] }, async ($, e, next) => {
    const verdict = await guardOutbound($, e, mode)
    return verdict === undefined ? next(e) : { deny: (verdict as { deny: string }).deny }
  }).catch(($, e, next) => onFailure(mode, next) ?? next(e))

  on('tool.call', { tool: /^mcp__/ }, async ($, e, next) => {
    // An MCP tool that names .leakstop.json may rewrite it: ask, as for Write, Edit and the shell, even when paused.
    if (JSON.stringify(e).includes('.leakstop.json')) {
      const guard = await checkConfig($, e.tool, '.leakstop.json', mode)
      if (guard !== undefined) return { deny: (guard as { deny: string }).deny }
    }
    const verdict = await guardOutbound($, e, mode)
    return verdict === undefined ? next(e) : { deny: (verdict as { deny: string }).deny }
  }).catch(($, e, next) => onFailure(mode, next) ?? next(e))

  // What a tool returns: a secret it printed is masked before the model or the transcript gets it.
  // The tool has already run, so a failure after it must not run it again: it withholds the output instead.
  on('tool.call', { tool: ['Bash', 'Read'] }, async ($, e, next) => {
    const r = await next(e)
    try {
      return await maskOutput($, e, r, mode)
    } catch {
      return mode === 'monitor' ? r : { deny: say.OUTPUT_FAILURE }
    }
  }).catch(($, e, next) => onFailure(mode, next) ?? next(e))

  on('tool.call', { tool: /^mcp__/ }, async ($, e, next) => {
    const r = await next(e)
    try {
      return await maskOutput($, e, r, mode)
    } catch {
      return mode === 'monitor' ? r : { deny: say.OUTPUT_FAILURE }
    }
  }).catch(($, e, next) => onFailure(mode, next) ?? next(e))
}

const displayPathOf = say.displayPath

files.hooks/commands.ts:
// Reads a Bash command as text and says what it is about to do that matters to
// LeakStop. Pure: no `$`, no I/O.
//
// It reads, it does not execute. A command built from variables, a script run
// with `python -c` or an encoded payload is not understood; the README says so.
// Everything here errs on the side of looking: a false positive is a question,
// a false negative is a leak.

import { classifyPath } from './detect.ts'

export type Segment = {
  /** Words with quotes and escapes resolved. Redirections are words of their own (`>`, `<`). */
  words: string[]
  /** Parallel to `words`: true when the word was written with quotes or a backslash (`\\grep`, `"grep"`). */
  quoted: boolean[]
  /** Segments joined by `|` share a pipeline id. */
  pipeline: number
}

/** Splits on `&&`, `||`, `;`, `&`, `|`, newlines and parentheses; skips heredoc bodies. */
export function parseCommand(command: string): Segment[] {
  return parseWithBodies(command).segments
}

/** `<<'EOF'` bodies are text, not shell: nothing in them is expanded or run. */
type Span = { start: number; end: number }

function parseWithBodies(command: string): { segments: Segment[]; literalBodies: Span[] } {
  const segments: Segment[] = []
  const literalBodies: Span[] = []
  let words: string[] = []
  let quoted: boolean[] = []
  let word = ''
  let hasWord = false
  let isQuoted = false
  let pipeline = 0
  let heredocs: { delimiter: string; isIndented: boolean; isLiteral: boolean }[] = []

  const pushWord = (text: string, wasQuoted: boolean): void => {
    words.push(text)
    quoted.push(wasQuoted)
  }
  const endWord = (): void => {
    if (hasWord) pushWord(word, isQuoted)
    word = ''
    hasWord = false
    isQuoted = false
  }
  const endSegment = (isPipe: boolean): void => {
    endWord()
    if (words.length > 0) segments.push({ words, quoted, pipeline })
    words = []
    quoted = []
    if (!isPipe) pipeline++
  }

  let i = 0
  while (i < command.length) {
    const char = command[i] as string
    const next = command[i + 1]

    if (char === '\\') {
      if (next !== undefined && next !== '\n') {
        word += next
        hasWord = true
        isQuoted = true
      }
      i += 2
      continue
    }
    if (char === "'") {
      const close = command.indexOf("'", i + 1)
      const end = close < 0 ? command.length : close
      word += command.slice(i + 1, end)
      hasWord = true
      isQuoted = true
      i = end + 1
      continue
    }
    if (char === '"') {
      i++
      hasWord = true
      isQuoted = true
      while (i < command.length && command[i] !== '"') {
        if (command[i] === '\\' && i + 1 < command.length) i++
        word += command[i]
        i++
      }
      i++
      continue
    }
    if (char === ' ' || char === '\t') {
      endWord()
      i++
      continue
    }
    if (char === '\n') {
      endSegment(false)
      i++
      // Skip the bodies of heredocs opened on the line that just ended.
      for (const heredoc of heredocs) {
        const start = i
        while (i < command.length) {
          const lineEnd = command.indexOf('\n', i)
          const line = command.slice(i, lineEnd < 0 ? command.length : lineEnd)
          i = lineEnd < 0 ? command.length : lineEnd + 1
          if ((heredoc.isIndented ? line.trim() : line) === heredoc.delimiter) break
        }
        if (heredoc.isLiteral) literalBodies.push({ start, end: i })
      }
      heredocs = []
      continue
    }
    if (char === '&' && word.endsWith('>')) {
      // `2>&1`: a file-descriptor duplication, not a control operator.
      word += char
      i++
      continue
    }
    if (char === '&' && next === '&') {
      endSegment(false)
      i += 2
      continue
    }
    if (char === '|' && next === '|') {
      endSegment(false)
      i += 2
      continue
    }
    if (char === '|') {
      endSegment(true)
      i++
      continue
    }
    if (char === ';' || char === '&' || char === '(' || char === ')' || char === '\x60') {
      endSegment(false)
      i++
      continue
    }
    if (char === '<' && next === '<' && command[i + 2] !== '<') {
      // Heredoc: `<<EOF`, `<<-EOF`, `<<'EOF'`. The body is skipped at the next newline.
      let j = i + 2
      const isIndented = command[j] === '-'
      if (isIndented) j++
      while (command[j] === ' ') j++
      const quote = command[j] === "'" || command[j] === '"' ? command[j] : undefined
      const isLiteral = quote !== undefined || command[j] === '\\'
      if (quote !== undefined) j++
      let delimiter = ''
      while (j < command.length && !/[\s;&|()<>'"]/.test(command[j] as string)) delimiter += command[j++]
      if (quote !== undefined && command[j] === quote) j++
      endWord()
      pushWord('<<', false)
      if (delimiter !== '') heredocs.push({ delimiter, isIndented, isLiteral })
      i = j
      continue
    }
    if (char === '<' || (char === '>' && !/^\d+$/.test(word))) {
      endWord()
      let op = char
      i++
      while (command[i] === char || (char === '>' && command[i] === '|')) op += command[i++]
      if (char === '>' && command[i] === '&') {
        // `>&2`: duplicate a descriptor.
        op += command[i++]
        while (/[0-9-]/.test(command[i] ?? '')) op += command[i++]
      }
      pushWord(op, false)
      continue
    }
    word += char
    hasWord = true
    i++
  }
  endSegment(false)
  return { segments, literalBodies }
}

// --- Programs --------------------------------------------------------------

const ASSIGNMENT = /^[A-Za-z_][A-Za-z0-9_]*=/
const WRAPPERS = new Set(['sudo', 'command', 'time', 'nohup', 'exec', 'builtin', 'nice', 'env'])

type Program = { name: string; args: string[]; isBareEnv: boolean; /** Invoked by its bare name, typed with no quotes or backslash and no wrapper before it. */ isPlain: boolean }

/** The program a segment runs, past assignments and wrappers (`sudo`, `env FOO=1`, `time`). */
function programOf(words: readonly string[], quoted: readonly boolean[] = []): Program {
  let i = 0
  let isEnv = false
  for (;;) {
    const word = words[i]
    if (word === undefined) break
    if (ASSIGNMENT.test(word)) {
      i++
    } else if (WRAPPERS.has(word)) {
      if (word === 'env') isEnv = true
      i++
      while (words[i]?.startsWith('-') === true) i++
    } else {
      break
    }
  }
  const first = words[i]
  if (first === undefined) return { name: '', args: [], isBareEnv: isEnv, isPlain: false }
  return { name: first.split('/').pop() ?? first, args: words.slice(i + 1), isBareEnv: false, isPlain: i === 0 && !first.includes('/') && quoted[i] !== true }
}

/** The files a segment sends its standard output to with `>` or `>>`. */
function outputTargets(args: readonly string[]): string[] {
  const targets: string[] = []
  for (let i = 0; i < args.length; i++) {
    if (/^>>?\|?$/.test(args[i] as string) && args[i + 1] !== undefined) targets.push(args[++i] as string)
  }
  return targets
}

const isFlag = (word: string): boolean => word.startsWith('-') && word.length > 1

/** Words that are operands: not flags and not the target of a redirection. */
function operands(args: readonly string[]): string[] {
  const out: string[] = []
  for (let i = 0; i < args.length; i++) {
    const word = args[i] as string
    if (/^>>?\|?$/.test(word)) {
      i++ // the target of an output redirection is written, not read
      continue
    }
    if (word === '<') continue // the next word is read: keep it
    if (word === '<<' || isFlag(word)) continue
    out.push(word)
  }
  return out
}

// --- Facts -----------------------------------------------------------------

/** Programs that print a file's contents, values included. `sed`, `awk` and `cut` are left out: they are how names are listed. */
const VIEWERS = new Set(['cat', 'head', 'tail', 'less', 'more', 'bat', 'nl', 'tac', 'strings', 'xxd', 'od', 'hexdump', 'grep', 'egrep', 'fgrep', 'rg', 'ag'])
/** The viewers whose output is the file itself, so listing names only is a faithful replacement. */
const PLAIN_VIEWERS = new Set(['cat', 'head', 'tail', 'less', 'more', 'bat', 'nl', 'tac'])

const SECRET_NAME = /(?:^|_)(?:KEY|TOKEN|SECRET|PASSWORD|PASSWD|PASS|CREDENTIALS?|AUTH|PRIVATE)(?:_|$)|APIKEY/i

export const isSecretName = (name: string): boolean => SECRET_NAME.test(name)

/**
 * Sensitive by path, or a glob that would match a sensitive path (`.env*`,
 * `*.pem`): the shell expands it, so the pattern itself is what the command shows.
 */
function isSensitiveOperand(operand: string): boolean {
  if (classifyPath(operand) !== undefined) return true
  if (!/[*?[]/.test(operand)) return false
  return [operand.replace(/[*?]/g, ''), operand.replace(/[*?]/g, 'x'), operand.replace(/\*/g, '.x')].some((guess) => classifyPath(guess) !== undefined)
}

/** A recursive `grep` or `rg` that prints lines (not just file names or counts). */
export type Search = {
  /** Where it looks: the folders it was given, or `.` when it was given none. */
  dirs: string[]
  /** Patterns of files it is told to skip (`--exclude`, `--exclude-dir`, `-g '!…'`). */
  excludes: string[]
  /** Patterns of files it is limited to (`--include`, `-g`); empty when it looks at everything. */
  includes: string[]
  /**
   * Files that git ignores are not searched. True for `rg` and `ag` unless told otherwise, and for the
   * plain `grep` command, which Claude Code's shell replaces with a search that honours `.gitignore`.
   */
  respectsIgnore: boolean
}

const SEARCHERS = new Set(['grep', 'egrep', 'fgrep', 'rg', 'ag'])
/** Flags whose value is the next word. */
const VALUE_FLAGS = new Set(['-e', '-f', '-m', '-A', '-B', '-C', '-d', '-D', '-g', '-t', '-T', '-j', '-M', '-E', '--include', '--exclude', '--exclude-dir', '--exclude-from', '--file', '--regexp', '--max-count', '--glob', '--iglob', '--type', '--type-not', '--threads', '--max-depth', '--context', '--before-context', '--after-context', '--directories', '--devices'])
/** `rg` and `ag` skip hidden and ignored files unless told otherwise. */
/** Flags that stop a search from honouring `.gitignore`. */
const NO_IGNORE = /^(?:--no-ignore(?:-[a-z-]+)?|--unrestricted|-u+|-U)$/
const REACHES_HIDDEN = /^(?:--hidden|-\.|--no-ignore(?:-[a-z-]+)?|--unrestricted|-u+|-U)$/
/** Flags that make the output file names or counts, never lines. */
const LIST_ONLY_LONG = /^--(?:files-with-matches|files-without-match|count|count-matches|quiet|silent|files)$/

type SearchParse = {
  /** The patterns and paths, with every flag and flag value removed. */
  paths: string[]
  /** File names or counts only: nothing here can print a line of a file. */
  isListOnly: boolean
  /** Set when the search is recursive and can reach files nobody named. */
  search?: Search
}

function parseSearch(name: string, args: readonly string[], isPlain: boolean): SearchParse {
  const isGrep = name === 'grep' || name === 'egrep' || name === 'fgrep'
  let isRecursive = !isGrep // rg and ag always are
  let reachesHidden = isGrep // grep reads dotfiles and ignored files
  let isIgnoreOff = false
  let isPatternGiven = false
  let isListOnly = false
  const words: string[] = []
  const excludes: string[] = []
  const includes: string[] = []

  for (let i = 0; i < args.length; i++) {
    const arg = args[i] as string
    if (/^>>?\|?$/.test(arg)) {
      i++ // the target of an output redirection
      continue
    }
    if (arg === '<' || arg === '<<') continue
    if (!isFlag(arg)) {
      words.push(arg)
      continue
    }
    const [flag, inline] = arg.startsWith('--') && arg.includes('=') ? [arg.slice(0, arg.indexOf('=')), arg.slice(arg.indexOf('=') + 1)] : [arg, undefined]
    const value = inline ?? (VALUE_FLAGS.has(flag) ? args[++i] : undefined)

    if (LIST_ONLY_LONG.test(flag)) isListOnly = true
    if (/^-[A-Za-z]*[lLcq][A-Za-z]*$/.test(flag) && !flag.startsWith('--') && !VALUE_FLAGS.has(flag)) isListOnly = true
    if (flag === '--recursive' || flag === '--dereference-recursive') isRecursive = true
    else if (isGrep && !flag.startsWith('--') && /^-[A-Za-z]*[rR][A-Za-z]*$/.test(flag) && !VALUE_FLAGS.has(flag)) isRecursive = true
    if (isGrep && (flag === '-d' || flag === '--directories') && value === 'recurse') isRecursive = true
    if (!isGrep && REACHES_HIDDEN.test(flag)) reachesHidden = true
    if (NO_IGNORE.test(flag)) isIgnoreOff = true
    if (flag === '-e' || flag === '-f' || flag === '--regexp' || flag === '--file') isPatternGiven = true

    if (value !== undefined) {
      if (flag === '--exclude' || flag === '--exclude-from') excludes.push(value)
      else if (flag === '--exclude-dir') excludes.push(`**/${value}/**`)
      else if (flag === '--include') includes.push(value)
      else if (flag === '-g' || flag === '--glob' || flag === '--iglob') (value.startsWith('!') ? excludes : includes).push(value.replace(/^!/, ''))
    }
  }
  const paths = isPatternGiven ? words : words.slice(1)
  if (isListOnly || !isRecursive || !reachesHidden) return { paths, isListOnly }
  const respectsIgnore = !isIgnoreOff && (isGrep ? name === 'grep' && isPlain : true)
  return { paths, isListOnly, search: { dirs: paths.length > 0 ? paths : ['.'], excludes, includes, respectsIgnore } }
}

export type GitOp =
  | { kind: 'add'; isAll: boolean; paths: string[]; dir?: string }
  | { kind: 'commit'; isAll: boolean; dir?: string; staging: { isAll: boolean; paths: string[] }[] }
  | { kind: 'push'; dir?: string }

export type CommandFacts = {
  /** Files a viewer would print that are sensitive by path (content check pending for `requiresToken` ones). */
  readFiles: string[]
  /** `printenv`, `env`, `export -p`, `set` or the environ file under /proc: the whole environment. */
  isEnvDump: boolean
  /** Secret-looking variables printed one by one: `printenv API_KEY`, `echo $TOKEN`. */
  secretVars: string[]
  git: GitOp[]
  /** The command changes `.leakstop.json`. */
  touchesConfig: boolean
  /** The command that prints names only instead, when the command is simple enough to rewrite. */
  namesOnly?: string
  /** Recursive searches that print matching lines and may reach files nobody named. */
  searches: Search[]
  /**
   * Where the command writes, when it does nothing but write: one `echo`, `printf` or `cat`
   * redirected to files, with no pipe, no `&&` and no command substitution. A secret in
   * such a command goes to those files and nowhere else.
   */
  writeTargets?: string[]
}

/**
 * Prints `NAME=<hidden>` for each assignment and nothing else, so no value and no
 * continuation line escapes. A name must be a plausible variable name (all upper
 * or all lower case, 48 characters at most): a base64 line that happens to end in
 * `=` inside a multi-line value is not one, and printing it would leak key material.
 */
const NAMES_ONLY_SED = String.raw`sed -nE 's/^[[:space:]]*(export[[:space:]]+)?([A-Z_][A-Z0-9_]{0,47}|[a-z_][a-z0-9_]{0,47})=.*/\2=<hidden>/p'`

export const shellQuote = (text: string): string => "'" + text.split("'").join("'\\''") + "'"

const READ_ONLY = new Set(['cat', 'less', 'more', 'head', 'tail', 'grep', 'egrep', 'rg', 'ls', 'stat', 'wc', 'file', 'diff', 'jq', 'test', '['])

function touchesConfig(segments: readonly Segment[]): boolean {
  return segments.some((segment) => {
    if (!segment.words.some((word) => word.includes('.leakstop.json'))) return false
    const program = programOf(segment.words)
    const isWrite = segment.words.some((word) => /^\d*>>?\|?$/.test(word))
    const isReadOnlyGit = program.name === 'git' && /^(?:diff|log|show|status|check-ignore|blame|ls-files)$/.test(program.args.find((a) => !isFlag(a)) ?? '')
    return isWrite || !(READ_ONLY.has(program.name) || isReadOnlyGit)
  })
}

const BACKTICKS = new RegExp('\\x60([^\\x60]*)\\x60', 'g')

/** Text of command substitutions (dollar-parenthesis and backticks), which can hide a command inside quotes. */
function substitutions(command: string): string[] {
  // The body of `<<'EOF'` is never expanded, so a `$(…)` or backticks in it are only text.
  let text = ''
  let at = 0
  for (const { start, end } of parseWithBodies(command).literalBodies) {
    text += command.slice(at, start)
    at = end
  }
  text += command.slice(at)
  const out: string[] = []
  for (const match of text.matchAll(/\$\(([^()]*)\)/g)) if (match[1] !== undefined) out.push(match[1])
  for (const match of text.matchAll(BACKTICKS)) if (match[1] !== undefined) out.push(match[1])
  return out
}

function gitOps(segments: readonly Segment[]): GitOp[] {
  const ops: GitOp[] = []
  const staging: { isAll: boolean; paths: string[] }[] = []
  let dir: string | undefined
  for (const segment of segments) {
    const program = programOf(segment.words)
    if (program.name === 'cd') {
      const target = program.args.find((a) => !isFlag(a))
      if (target !== undefined && !/^[~$-]/.test(target)) dir = dir === undefined || target.startsWith('/') ? target : `${dir}/${target}`
      continue
    }
    if (program.name !== 'git') continue
    // Global options before the subcommand: -C <dir>, -c k=v, --no-pager, ...
    let gitDir = dir
    const args = program.args
    let i = 0
    while (i < args.length && isFlag(args[i] as string)) {
      const flag = args[i] as string
      if (flag === '-C' && args[i + 1] !== undefined) {
        const target = args[i + 1] as string
        gitDir = gitDir === undefined || target.startsWith('/') ? target : `${gitDir}/${target}`
        i += 2
      } else if (flag === '-c' || flag === '--git-dir' || flag === '--work-tree') {
        i += 2
      } else {
        i++
      }
    }
    const sub = args[i]
    const rest = args.slice(i + 1)
    const withDir = <T extends GitOp>(op: T): T => (gitDir === undefined ? op : { ...op, dir: gitDir })
    if (sub === 'add') {
      const paths = operands(rest)
      const isAll = rest.some((a) => a === '-A' || a === '--all' || a === '-u' || a === '--update') || paths.some((p) => p === '.' || p === ':/' || p === '*' || p === './')
      staging.push({ isAll, paths })
      ops.push(withDir({ kind: 'add', isAll, paths }))
    } else if (sub === 'commit') {
      const isAll = rest.some((a) => a === '--all' || /^-[A-Za-z]*a[A-Za-z]*$/.test(a))
      ops.push(withDir({ kind: 'commit', isAll, staging: [...staging] }))
    } else if (sub === 'push') {
      ops.push(withDir({ kind: 'push' }))
    }
  }
  return ops
}

/**
 * `git` subcommands that print what a file holds or held: a blob, a patch or annotated lines.
 * `git diff` is left out: on an ignored or untracked `.env`, the usual case, it prints nothing.
 */
const GIT_PRINTERS = new Set(['show', 'cat-file', 'blame', 'grep'])
/** `git log` prints file contents only with a patch. */
const GIT_LOG_PATCH = /^(?:-p|-u|--patch|--patch-with-stat|--patch-with-raw|-L.*|--full-diff)$/

/**
 * Sensitive files a `git` command prints from history or the index: `git show HEAD:.env`,
 * `git cat-file -p main:.env`, `git log -p -- .env`.
 */
function gitPrintedFiles(args: readonly string[]): string[] {
  let i = 0
  while (i < args.length && isFlag(args[i] as string)) i += ['-C', '-c', '--git-dir', '--work-tree'].includes(args[i] as string) ? 2 : 1
  const sub = args[i]
  const rest = args.slice(i + 1)
  if (sub === undefined || !(GIT_PRINTERS.has(sub) || (sub === 'log' && rest.some((a) => GIT_LOG_PATCH.test(a))))) return []
  const files: string[] = []
  for (const word of operands(rest)) {
    // `<rev>:<path>` or `:<path>` (the index); a bare word is a path or a revision.
    const colon = word.indexOf(':')
    const path = colon >= 0 && !word.includes('://') ? word.slice(colon + 1) : word
    if (path !== '' && isSensitiveOperand(path)) files.push(path)
  }
  return files
}

/** The name patterns a `find` matches and the program its `-exec` runs, if any. */
function findFacts(args: readonly string[]): { patterns: string[]; runs?: string } {
  const patterns: string[] = []
  let runs: string | undefined
  for (let i = 0; i < args.length; i++) {
    const word = args[i] as string
    if (['-name', '-iname', '-path', '-ipath', '-wholename', '-iwholename'].includes(word) && args[i + 1] !== undefined) patterns.push(args[++i] as string)
    else if (['-exec', '-execdir', '-ok', '-okdir'].includes(word) && args[i + 1] !== undefined && runs === undefined) runs = programOf(args.slice(i + 1)).name
  }
  return runs === undefined ? { patterns } : { patterns, runs }
}

const dedupe = <T>(items: readonly T[]): T[] => {
  const seen = new Set<string>()
  return items.filter((item) => {
    const key = JSON.stringify(item)
    return seen.has(key) ? false : (seen.add(key), true)
  })
}

function analyzeSegments(command: string, segments: readonly Segment[], depth: number): CommandFacts {
  const readFiles: string[] = []
  const secretVars: string[] = []
  let isEnvDump = false
  const searches: Search[] = []
  /** Files this command fills with the value of a secret variable, and which variables. */
  const written = new Map<string, string[]>()

  for (const segment of segments) {
    const { name, args, isBareEnv, isPlain } = programOf(segment.words, segment.quoted)
    if (written.size > 0 && (VIEWERS.has(name) || name === 'sed' || name === 'awk')) {
      for (const file of operands(args)) secretVars.push(...(written.get(file) ?? []))
    }
    const isFiltered = segments.some(
      (other) => other !== segment && other.pipeline === segment.pipeline && ['cut', 'wc'].includes(programOf(other.words).name),
    )

    if (isBareEnv || (name === 'printenv' && operands(args).length === 0)) {
      if (!isFiltered) isEnvDump = true
    } else if (name === 'printenv') {
      for (const variable of operands(args)) if (isSecretName(variable)) secretVars.push(variable)
    } else if ((name === 'export' || name === 'declare' || name === 'typeset') && args.some((a) => /^-[a-z]*[px][a-z]*$/.test(a)) && operands(args).length === 0) {
      if (!isFiltered) isEnvDump = true
    } else if (name === 'set' && args.length === 0) {
      if (!isFiltered) isEnvDump = true
    } else if (name === 'echo' || name === 'printf') {
      const printed: string[] = []
      for (const match of segment.words.join(' ').matchAll(/\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?/g)) {
        if (match[1] !== undefined && isSecretName(match[1])) printed.push(match[1])
      }
      // Redirected to a file, the value is not printed; reading that file back in the same command is.
      const targets = outputTargets(args)
      if (targets.length === 0) secretVars.push(...printed)
      else if (printed.length > 0) for (const target of targets) written.set(target, printed)
    } else if (SEARCHERS.has(name)) {
      const parsed = parseSearch(name, args, isPlain)
      if (parsed.search !== undefined) searches.push(parsed.search)
      // A search that names a sensitive file is a plain read of it, unless it only lists names or counts.
      if (!parsed.isListOnly) {
        for (const file of parsed.paths) {
          if (/^\/proc\/[^/]+\/environ$/.test(file)) isEnvDump = true
          else if (isSensitiveOperand(file)) readFiles.push(file)
        }
      }
    } else if (VIEWERS.has(name)) {
      for (const file of operands(args)) {
        if (/^\/proc\/[^/]+\/environ$/.test(file)) isEnvDump = true
        else if (isSensitiveOperand(file)) readFiles.push(file)
      }
    } else if (name === 'git') {
      readFiles.push(...gitPrintedFiles(args))
    } else if (name === 'find') {
      const { patterns, runs } = findFacts(args)
      if (runs !== undefined && VIEWERS.has(runs)) readFiles.push(...patterns.filter(isSensitiveOperand))
    } else if (name === 'xargs') {
      // `find -name .env | xargs cat`: the files come from a `find` earlier in the same pipeline.
      const runs = programOf(args.filter((a) => !isFlag(a))).name
      if (VIEWERS.has(runs)) {
        for (const other of segments) {
          if (other === segment || other.pipeline !== segment.pipeline) continue
          const source = programOf(other.words)
          if (source.name === 'find') readFiles.push(...findFacts(source.args).patterns.filter(isSensitiveOperand))
        }
      }
    }
  }

  let git = gitOps(segments)
  let touches = touchesConfig(segments)

  if (depth < 2) {
    for (const inner of substitutions(command)) {
      const facts = analyzeSegments(inner, parseCommand(inner), depth + 1)
      readFiles.push(...facts.readFiles)
      secretVars.push(...facts.secretVars)
      isEnvDump ||= facts.isEnvDump
      searches.push(...facts.searches)
      git = [...git, ...facts.git]
      touches ||= facts.touchesConfig
    }
  }

  return { readFiles: [...new Set(readFiles)], isEnvDump, secretVars: [...new Set(secretVars)], searches: dedupe(searches), git, touchesConfig: touches, namesOnly: namesOnlyFor(segments, readFiles, isEnvDump) }
}

/** The replacement that lists names only, for a command that is one plain view of env files or the bare environment. */
function namesOnlyFor(segments: readonly Segment[], readFiles: readonly string[], isEnvDump: boolean): string | undefined {
  if (segments.length !== 1) return undefined
  const { name, args, isBareEnv } = programOf((segments[0] as Segment).words)
  if (isEnvDump && (isBareEnv || name === 'printenv') && operands(args).length === 0) return `env | ${NAMES_ONLY_SED}`
  if (readFiles.length > 0 && PLAIN_VIEWERS.has(name)) {
    const others = operands(args).filter((word) => !/^\d+$/.test(word))
    if (others.length === readFiles.length && readFiles.every((file) => classifyPath(file)?.kind === 'env')) {
      return `${NAMES_ONLY_SED} ${readFiles.map((file) => shellQuote(file.startsWith('-') ? `./${file}` : file)).join(' ')}`
    }
  }
  return undefined
}

const WRITERS = new Set(['echo', 'printf', 'cat'])

/** `sed` options that edit the file in place: `-i`, `-i.bak`, `-Ei`, `--in-place`. */
const isInPlace = (word: string): boolean => /^-[EnrsuzS]*i/.test(word) || word === '--in-place' || word.startsWith('--in-place=')

/** The files `sed -i` rewrites, or `undefined` when it is not an in-place edit of named files. */
function inPlaceTargets(args: readonly string[]): string[] | undefined {
  if (!args.some(isInPlace)) return undefined
  const words: string[] = []
  for (let i = 0; i < args.length; i++) {
    const word = args[i] as string
    if (word === '-i' && args[i + 1] === '') i++ // macOS: the backup suffix is its own, empty, word
    else if (word === '-e' || word === '-f') {
      words.push('-e')
      i++
    } else if (!isFlag(word) || word === '-') words.push(word)
  }
  const script = words.includes('-e') ? 0 : 1
  const targets = words.filter((w) => w !== '-e').slice(script)
  return targets.length > 0 ? targets : undefined
}

/** True when a `tee` segment sends its standard output to /dev/null, so it writes the files and prints nothing. */
const isQuietTee = (args: readonly string[]): boolean => {
  for (let i = 0; i < args.length; i++) {
    if (/^>>?$/.test(args[i] as string) && args[i + 1] === '/dev/null') return true
  }
  return false
}

/** The files a command only writes to, or `undefined` when it does anything else as well. */
function writeTargetsOf(command: string, segments: readonly Segment[]): string[] | undefined {
  if (substitutions(command).length > 0) return undefined
  if (segments.length === 1) {
    const { name, args } = programOf((segments[0] as Segment).words)
    if (name === 'sed') return inPlaceTargets(args)
    if (!WRITERS.has(name)) return undefined
    const targets = outputTargets(args)
    return targets.length > 0 ? targets : undefined
  }
  // `echo … | tee -a file > /dev/null`: tee prints what it writes, so only the quiet form is a plain write.
  if (segments.length === 2 && (segments[0] as Segment).pipeline === (segments[1] as Segment).pipeline) {
    const writer = programOf((segments[0] as Segment).words)
    const tee = programOf((segments[1] as Segment).words)
    if (!['echo', 'printf'].includes(writer.name) || outputTargets(writer.args).length > 0) return undefined
    if (tee.name !== 'tee' || !isQuietTee(tee.args)) return undefined
    const targets = operands(tee.args).filter((word) => word !== '/dev/null')
    return targets.length > 0 ? targets : undefined
  }
  return undefined
}

export function analyzeCommand(command: string): CommandFacts {
  const segments = parseCommand(command)
  const facts = analyzeSegments(command, segments, 0)
  const writeTargets = writeTargetsOf(command, segments)
  return writeTargets === undefined ? facts : { ...facts, writeTargets }
}

files.hooks/config.ts:
// `.leakstop.json`: parsing and validation. Pure: no `$`, no I/O.
//
// The file comes from the repository, so it is untrusted: a cloned project must
// not be able to lower the protection or slow the scanner down. Whatever is
// wrong with it is ignored with a warning, and ignoring a setting always means
// the stricter default. The file can only add rules or relax medium findings;
// the protection level itself (`mode`) lives in the user's own settings.

import type { StoredConfig, StoredRule } from '../types'
import type { Rule, Severity } from './rules.ts'

/** A config file larger than this is ignored. */
export const MAX_CONFIG_CHARS = 256 * 1024

const MAX_IGNORE_PATHS = 200
const MAX_ALLOW_FINGERPRINTS = 500
const MAX_CUSTOM_RULES = 50
const MAX_PATTERN_CHARS = 200
const MAX_REGEX_CHARS = 200
const KNOWN_KEYS = new Set(['ignorePaths', 'allowFingerprints', 'customRules'])
const KNOWN_RULE_KEYS = new Set(['id', 'regex', 'severity', 'label', 'prefix', 'group', 'minEntropy'])

export const EMPTY_CONFIG: StoredConfig = { ignorePaths: [], allowFingerprints: [], customRules: [], warnings: [] }

// --- Globs for ignorePaths -------------------------------------------------

/**
 * `tests/fixtures/**`, `*.json`, `examples/`. A pattern with no slash matches at any
 * depth, as in .gitignore; `**` crosses folders, `*` and `?` do not.
 */
export function globToRegExp(glob: string): RegExp | undefined {
  const pattern = glob.replace(/\\/g, '/').replace(/^\.\//, '')
  if (pattern === '' || pattern.length > MAX_PATTERN_CHARS) return undefined
  if ((pattern.match(/\*\*/g) ?? []).length > 3) return undefined

  let source = ''
  for (let i = 0; i < pattern.length; i++) {
    const char = pattern[i] as string
    if (char === '*' && pattern[i + 1] === '*') {
      const isFolder = pattern[i + 2] === '/'
      source += isFolder ? '(?:.*/)?' : '.*'
      i += isFolder ? 2 : 1
    } else if (char === '*') {
      source += '[^/]*'
    } else if (char === '?') {
      source += '[^/]'
    } else {
      source += char.replace(/[.+^${}()|[\]\\]/g, '\\$&')
    }
  }
  if (pattern.endsWith('/')) source += '.*'
  const anywhere = pattern.includes('/') ? '' : '(?:.*/)?'
  return new RegExp(`^${anywhere}${source}$`)
}

/** A longer path never matches: globs come from the repository and can be slow on a very long path, and ignoring a path only ever relaxes. */
const MAX_PATH_CHARS = 512

/** True when `path` matches any pattern. Patterns that do not compile match nothing. */
export function matchesAny(path: string, patterns: readonly string[]): boolean {
  if (path.length > MAX_PATH_CHARS) return false
  const normalized = path.replace(/\\/g, '/').replace(/^\.\//, '')
  return patterns.some((pattern) => globToRegExp(pattern)?.test(normalized) === true)
}

// --- Custom rules ------------------------------------------------------------

/** Walks a regex source and says whether a group holding an unbounded repeat is itself repeated without bound. */
function hasNestedQuantifier(source: string): boolean {
  const stack: boolean[] = []
  let unbounded = 0
  let i = 0
  const isUnboundedAt = (index: number): boolean => {
    const char = source[index]
    if (char === '*' || char === '+') return true
    if (char === '{') return /^\{\d+,\}/.test(source.slice(index))
    return false
  }
  while (i < source.length) {
    const char = source[i] as string
    if (char === '\\') {
      i += 2
      continue
    }
    if (char === '[') {
      i++
      while (i < source.length && source[i] !== ']') i += source[i] === '\\' ? 2 : 1
      i++ // the quantifier after the class, if any, is counted on the next turn
      continue
    }
    if (char === '(') {
      stack.push(false)
    } else if (char === ')') {
      const held = stack.pop() ?? false
      if (held && isUnboundedAt(i + 1)) return true
      if (held && stack.length > 0) stack[stack.length - 1] = true
    } else if (isUnboundedAt(i) && i > 0) {
      unbounded++
      if (stack.length > 0) stack[stack.length - 1] = true
    }
    i++
  }
  // `.*.*.*` and friends are slow without being nested.
  return unbounded > 4
}

const HOSTILE_INPUTS: readonly string[] = [
  'a'.repeat(4000),
  'ab'.repeat(2000),
  ' '.repeat(4000),
  '0123456789abcdef'.repeat(250),
  `${'a'.repeat(22)}!`,
  `${'a '.repeat(11)}!`,
  `${'ab'.repeat(11)}!`,
]
const BUDGET_MS = 40

/**
 * Why a custom regex cannot be used, or `undefined` when it can. It must be
 * short, free of backreferences and lookarounds, free of nested unbounded
 * repeats, and quick on hostile inputs: a rule that makes the scanner run out of
 * its 10 seconds would make Claude Code skip the hook and let the call through.
 */
export function regexProblem(source: string): string | undefined {
  if (source.length === 0 || source.length > MAX_REGEX_CHARS) return `must be 1 to ${MAX_REGEX_CHARS} characters`
  if (/\\[1-9k]/.test(source)) return 'backreferences are not allowed'
  if (/\(\?<?[=!]/.test(source)) return 'lookaheads and lookbehinds are not allowed'
  let regex: RegExp
  try {
    regex = new RegExp(source, 'g')
  } catch {
    return 'is not a valid regular expression'
  }
  if (regex.test('')) return 'matches the empty string'
  if (hasNestedQuantifier(source)) return 'repeats a repeat (for example (a+)+), which can run for ever'
  for (const input of HOSTILE_INPUTS) {
    const startedAt = performance.now()
    input.match(regex)
    if (performance.now() - startedAt > BUDGET_MS) return 'is too slow on long input'
  }
  return undefined
}

function parseRule(raw: unknown, index: number, seen: Set<string>): { rule?: StoredRule; warning?: string } {
  const at = `customRules[${index}]`
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return { warning: `${at} is not an object, so it was ignored` }
  const entry = raw as Record<string, unknown>
  const unknown = Object.keys(entry).filter((key) => !KNOWN_RULE_KEYS.has(key))
  if (unknown.length > 0) return { warning: `${at} has unknown fields (${unknown.join(', ')}), so it was ignored` }

  const { id, regex, severity, label, prefix, group, minEntropy } = entry
  if (typeof id !== 'string' || !/^[a-z0-9][a-z0-9-]{0,39}$/.test(id)) return { warning: `${at}.id must be lowercase letters, digits and dashes (40 at most), so the rule was ignored` }
  if (seen.has(id)) return { warning: `${at}.id "${id}" is used twice, so the second rule was ignored` }
  if (typeof regex !== 'string') return { warning: `${at}.regex must be a string, so the rule was ignored` }
  if (severity !== 'critical' && severity !== 'medium') return { warning: `${at}.severity must be "critical" or "medium", so the rule was ignored` }
  const problem = regexProblem(regex)
  if (problem !== undefined) return { warning: `${at}.regex ${problem}, so the rule was ignored` }

  const rule: StoredRule = { id: `custom:${id}`, label: typeof label === 'string' && label.length > 0 ? label.slice(0, 60) : `Custom rule ${id}`, severity, source: regex }
  if (typeof prefix === 'string' && prefix.length > 0 && prefix.length <= 20) rule.prefix = prefix
  if (typeof group === 'number' && Number.isInteger(group) && group >= 1 && group <= 9) rule.groups = [group]
  if (typeof minEntropy === 'number' && minEntropy >= 0 && minEntropy <= 6) rule.minEntropy = minEntropy
  seen.add(id)
  return { rule }
}

/** A stored rule as the scanner takes it. `undefined` when it no longer compiles. */
export function toRule(stored: StoredRule): Rule | undefined {
  try {
    const rule: Rule = { id: stored.id, label: stored.label, severity: stored.severity as Severity, regex: new RegExp(stored.source, 'g') }
    if (stored.prefix !== undefined) rule.prefix = stored.prefix
    if (stored.groups !== undefined) rule.groups = stored.groups
    if (stored.minEntropy !== undefined) rule.minEntropy = stored.minEntropy
    return rule
  } catch {
    return undefined
  }
}

// --- The file ----------------------------------------------------------------

const FINGERPRINT = /^sha256:[0-9a-f]{16}$/

function stringList(value: unknown, field: string, max: number, warnings: string[], accept: (item: string) => boolean, why: string): string[] {
  if (!Array.isArray(value)) {
    warnings.push(`${field} must be a list of strings, so it was ignored`)
    return []
  }
  const kept: string[] = []
  let dropped = 0
  for (const item of value.slice(0, max)) {
    if (typeof item === 'string' && accept(item)) kept.push(item)
    else dropped++
  }
  if (value.length > max) warnings.push(`${field} has more than ${max} entries; the rest were ignored`)
  if (dropped > 0) warnings.push(`${field}: ${dropped} entr${dropped === 1 ? 'y' : 'ies'} ignored (${why})`)
  return [...new Set(kept)]
}

/**
 * Reads the text of `.leakstop.json`. Never throws: a malformed file gives the
 * defaults and a warning, an unknown or malformed field is ignored with a
 * warning, and the valid fields are kept.
 */
export function parseConfig(text: string): StoredConfig {
  if (text.length > MAX_CONFIG_CHARS) return { ...EMPTY_CONFIG, warnings: ['.leakstop.json is larger than 256 KiB, so it was ignored'] }
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return { ...EMPTY_CONFIG, warnings: ['.leakstop.json is not valid JSON, so the defaults apply'] }
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { ...EMPTY_CONFIG, warnings: ['.leakstop.json must hold a JSON object, so the defaults apply'] }
  }

  const root = parsed as Record<string, unknown>
  const warnings: string[] = []
  const unknown = Object.keys(root).filter((key) => !KNOWN_KEYS.has(key))
  if (unknown.length > 0) warnings.push(`unknown field${unknown.length === 1 ? '' : 's'} ignored: ${unknown.join(', ')}`)

  const ignorePaths =
    root.ignorePaths === undefined
      ? []
      : stringList(root.ignorePaths, 'ignorePaths', MAX_IGNORE_PATHS, warnings, (item) => globToRegExp(item) !== undefined, 'empty, too long or too many **')
  const allowFingerprints =
    root.allowFingerprints === undefined
      ? []
      : stringList(root.allowFingerprints, 'allowFingerprints', MAX_ALLOW_FINGERPRINTS, warnings, (item) => FINGERPRINT.test(item), 'not a sha256: fingerprint')

  const customRules: StoredRule[] = []
  if (root.customRules !== undefined) {
    if (!Array.isArray(root.customRules)) {
      warnings.push('customRules must be a list, so it was ignored')
    } else {
      if (root.customRules.length > MAX_CUSTOM_RULES) warnings.push(`customRules has more than ${MAX_CUSTOM_RULES} rules; the rest were ignored`)
      const seen = new Set<string>()
      root.customRules.slice(0, MAX_CUSTOM_RULES).forEach((raw, index) => {
        const { rule, warning } = parseRule(raw, index, seen)
        if (rule !== undefined) customRules.push(rule)
        if (warning !== undefined) warnings.push(warning)
      })
    }
  }

  return { ignorePaths, allowFingerprints, customRules, warnings }
}

files.hooks/detect.ts:
// Detection: path rules, regexes, entropy, allowlist and false-positive
// exclusions. Pure functions: no `$`, no I/O, no state.
//
// A Finding carries the secret's `value` so the caller can fingerprint and mask
// it. It must never be stored, logged or sent anywhere: turn it into a
// MaskedFinding with `describe` (mask.ts) and drop it.

import { NPMRC_RULES, PYPIRC_RULES, RULES } from './rules.ts'
import type { Rule, Severity } from './rules.ts'

export type { Rule, Severity } from './rules.ts'

/** `$.fs.read` accepts 4 MiB; anything larger is skipped, not scanned. */
export const MAX_SCAN_CHARS = 4 * 1024 * 1024

export type Finding = {
  ruleId: string
  label: string
  severity: Severity
  /** 1-based, relative to the scanned text. */
  line: number
  start: number
  end: number
  /** The secret itself. In memory only. */
  value: string
  prefix?: string
  isGeneric: boolean
}

export type ScanResult = {
  findings: Finding[]
  /** True when the text was over MAX_SCAN_CHARS and nothing was scanned. */
  isSkipped: boolean
  /** True when the custom rules ran out of their time budget and did not cover all the text. */
  isPartial: boolean
}

export type ScanOptions = {
  /** Path of the file the text is going to, when there is one. */
  path?: string
  /** Extra rules, already validated by the caller. */
  extraRules?: readonly Rule[]
}

// --- Entropy ---------------------------------------------------------------

/** Shannon entropy of `text`, in bits per character. */
export function entropy(text: string): number {
  if (text.length === 0) return 0
  const counts = new Map<string, number>()
  for (const char of text) counts.set(char, (counts.get(char) ?? 0) + 1)
  let bits = 0
  for (const count of counts.values()) {
    const p = count / text.length
    bits -= p * Math.log2(p)
  }
  return bits
}

// --- Paths -----------------------------------------------------------------

export type PathKind = 'env' | 'private-key' | 'credentials' | 'terraform-state' | 'package-auth'

export type PathClass = {
  kind: PathKind
  label: string
  /** The file is only sensitive when it holds a token (.npmrc, .pypirc). */
  requiresToken: boolean
}

const baseName = (path: string): string => path.split(/[\\/]/).pop()?.toLowerCase() ?? ''

const ENV_SAFE_SUFFIX = /\.(?:example|sample|template|dist|defaults)$/

/** The sensitive-file rules, by path alone. `undefined`: not sensitive. */
export function classifyPath(path: string): PathClass | undefined {
  const name = baseName(path)
  if (name === '') return undefined
  if (/^\.env(?:\..+)?$/.test(name) || /\.env$/.test(name)) {
    return ENV_SAFE_SUFFIX.test(name) ? undefined : { kind: 'env', label: 'Environment file', requiresToken: false }
  }
  if (/^id_(?:rsa|dsa|ecdsa|ed25519)(?:\..*)?$/.test(name)) {
    return name.endsWith('.pub') ? undefined : { kind: 'private-key', label: 'SSH private key', requiresToken: false }
  }
  if (/\.(?:pem|key|p12|pfx|jks|keystore)$/.test(name)) {
    return { kind: 'private-key', label: 'Key or certificate file', requiresToken: false }
  }
  if (name === 'credentials.json' || /^service-account.*\.json$/.test(name)) {
    return { kind: 'credentials', label: 'Credentials file', requiresToken: false }
  }
  if (/\.tfstate(?:\.backup)?$/.test(name)) {
    return { kind: 'terraform-state', label: 'Terraform state', requiresToken: false }
  }
  if (name === '.npmrc' || name === '.pypirc') {
    return { kind: 'package-auth', label: 'Package registry config', requiresToken: true }
  }
  return undefined
}

/** Firebase's client config files: the Google API key in them identifies the app and is committed by design, so it only warns. */
const FIREBASE_CLIENT_FILES = new Set(['googleservice-info.plist', 'google-services.json'])

const LOCKFILES = new Set([
  'package-lock.json',
  'npm-shrinkwrap.json',
  'yarn.lock',
  'pnpm-lock.yaml',
  'bun.lock',
  'cargo.lock',
  'poetry.lock',
  'pipfile.lock',
  'composer.lock',
  'gemfile.lock',
  'go.sum',
])

// --- Allowlist and false-positive exclusions -------------------------------

/** Long words and shapes that a real credential never contains by chance. */
const STRONG_PLACEHOLDER = /example|placeholder|changeme|change[-_ ]?me|dummy|sample|redacted|insert|replace|(?:^|[-_])your[-_]|<[^>]*>|\$\{[^}]*\}|\{\{[^}]*\}\}|^\$[A-Za-z_]|^%\(/i
/** Short fragments that a random key can contain by chance (`-my_`, `xxxx`): they only count in a low-entropy value. */
const WEAK_PLACEHOLDER = /(?:^|[-_])my[-_]|todo|fixme|x{4,}|\*{4,}|•{3,}|\.{3,}|0{8,}|#{4,}/i
/** A random 20+ character key is above this; `your-key-here` and `xxxxxxxx` are well below. */
const RANDOM_ENTROPY = 4.2
const WEAK_PASSWORDS = new Set(['password', 'passwd', 'pass', 'pwd', 'secret', 'admin', 'root', 'test', 'user', 'guest', 'postgres', 'mysql', 'redis'])

/**
 * Placeholders and documentation examples: `your-api-key`, `changeme`,
 * `<TOKEN>`, `xxxx…`, AWS's `…EXAMPLE` keys and anything that is a reference
 * to a variable instead of a value. A high-entropy value is never called a
 * placeholder because of a short fragment: that would let a real key through.
 */
export function isPlaceholder(value: string): boolean {
  if (STRONG_PLACEHOLDER.test(value)) return true
  if (WEAK_PLACEHOLDER.test(value) && entropy(value) < RANDOM_ENTROPY) return true
  if (WEAK_PASSWORDS.has(value.toLowerCase())) return true
  // One repeated character, with or without a known prefix.
  return /^(.)\1+$/.test(value.replace(/^[A-Za-z]{1,6}[-_]/, ''))
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const GIT_SHA = /^[0-9a-f]{40}$/i
const INTEGRITY = /^sha(?:1|256|384|512)-[A-Za-z0-9+/=]+$/
const DATA_URI = /^data:[a-z]+\/[a-z0-9.+-]+;base64,/i
const DOTTED_PATH = /^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)+$/
const CONSTANT_NAME = /^[A-Z][A-Z0-9_]+$/
const WORD_LIST = /^[A-Za-z]+(?:[-_][A-Za-z]+)+$/

/** Typical false positives of the generic heuristic: hashes, ids, code, URLs and paths. */
export function isFalsePositive(value: string): boolean {
  return (
    UUID.test(value) ||
    GIT_SHA.test(value) ||
    INTEGRITY.test(value) ||
    DATA_URI.test(value) ||
    DOTTED_PATH.test(value) || // process.env.API_KEY, os.environ.get
    CONSTANT_NAME.test(value) || // the name of an environment variable
    WORD_LIST.test(value) || // some-config-value
    value.includes('://') ||
    value.startsWith('/') ||
    value.startsWith('./') ||
    value.startsWith('../')
  )
}

// --- Scanning --------------------------------------------------------------

/**
 * Custom rules come from the repository, so they run under a cost bound whatever
 * they are: over windows of this many characters, overlapping by the difference
 * with STRIDE, and within a total time budget. A slow pattern can then cost at
 * most a window's worth per window, and never the hook's 10 seconds.
 */
const WINDOW = 600
const STRIDE = 400
const CUSTOM_BUDGET_MS = 500

type Budget = { deadline: number; isPartial: boolean }

function* windowedMatches(regex: RegExp, text: string, budget: Budget): Generator<RegExpMatchArray> {
  const seen = new Set<number>()
  for (let from = 0; from < text.length; from += STRIDE) {
    if (performance.now() > budget.deadline) {
      budget.isPartial = true
      return
    }
    for (const match of text.slice(from, from + WINDOW).matchAll(regex)) {
      const start = from + (match.index ?? 0)
      if (seen.has(start)) continue
      seen.add(start)
      match.index = start
      yield match
    }
    if (from + WINDOW >= text.length) return
  }
}

/** 1-based line of each offset, from a table of line starts built once. */
function lineIndex(text: string): (offset: number) => number {
  const starts = [0]
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) === 10) starts.push(i + 1)
  return (offset) => {
    let low = 0
    let high = starts.length - 1
    while (low < high) {
      const mid = (low + high + 1) >> 1
      if ((starts[mid] ?? 0) <= offset) low = mid
      else high = mid - 1
    }
    return low + 1
  }
}

const overlaps = (a: Finding, b: Finding): boolean => a.start < b.end && b.start < a.end

/** Scans `text` for secrets. Findings come back in order of position. */
export function scanText(text: string, options: ScanOptions = {}): ScanResult {
  if (text.length > MAX_SCAN_CHARS) return { findings: [], isSkipped: true, isPartial: false }

  const name = options.path === undefined ? '' : baseName(options.path)
  const rules: Rule[] = [...RULES, ...(options.extraRules ?? [])]
  if (name === '.npmrc') rules.push(...NPMRC_RULES)
  if (name === '.pypirc') rules.push(...PYPIRC_RULES)
  // Lockfiles are full of integrity hashes; only precise provider rules apply.
  const isLockfile = LOCKFILES.has(name)

  const lineOf = lineIndex(text)
  const found: Finding[] = []
  const budget: Budget = { deadline: performance.now() + CUSTOM_BUDGET_MS, isPartial: false }

  for (const rule of rules) {
    if (isLockfile && rule.isGeneric) continue
    const matches = rule.id.startsWith('custom:') ? windowedMatches(rule.regex, text, budget) : text.matchAll(rule.regex)
    for (const match of matches) {
      const groupValue = rule.groups?.map((g) => match[g]).find((v) => v !== undefined)
      const value = rule.groups === undefined ? match[0] : groupValue
      if (value === undefined || value === '') continue
      if (isPlaceholder(value)) continue
      if (rule.accept !== undefined && !rule.accept(value, match)) continue
      if (rule.minEntropy !== undefined && entropy(value) < rule.minEntropy) continue
      if (rule.isGeneric === true && isFalsePositive(value)) continue
      const start = match.index ?? 0
      found.push({
        ruleId: rule.id,
        label: rule.label,
        severity: rule.id === 'google-api-key' && FIREBASE_CLIENT_FILES.has(name) ? 'medium' : rule.severity,
        line: lineOf(start),
        start,
        end: start + match[0].length,
        value,
        prefix: rule.prefix,
        isGeneric: rule.isGeneric === true,
      })
    }
  }

  // A precise finding wins over a heuristic one on the same text.
  const precise = found.filter((f) => !f.isGeneric)
  const findings = [...precise, ...found.filter((f) => f.isGeneric && !precise.some((p) => overlaps(f, p)))]
  findings.sort((a, b) => a.start - b.start)
  return { findings, isSkipped: false, isPartial: budget.isPartial }
}

/** Write: the whole content and the path. */
export function scanWrite(path: string, content: string, options: Omit<ScanOptions, 'path'> = {}): ScanResult {
  return scanText(content, { ...options, path })
}

/**
 * Edit: only the new text, so secrets that were already in the file do not
 * warn. A secret that is also in the replaced text was there before.
 */
export function scanEdit(path: string, oldString: string, newString: string, options: Omit<ScanOptions, 'path'> = {}): ScanResult {
  const result = scanText(newString, { ...options, path })
  return { ...result, findings: result.findings.filter((f) => !oldString.includes(f.value)) }
}

