// Scans the lines a diff adds. Pure: no `$`, no I/O.
//
// `git diff --cached` says what a commit would contain and `git log -p` what a
// push would publish. Only added lines matter: a secret that is being removed
// is not being leaked.

import { scanText } from './detect.ts'
import type { Finding, Rule } from './detect.ts'

export type AddedFile = {
  path: string
  /** The added lines, in order. */
  lines: string[]
  /** The line of each added line in the new file. */
  numbers: number[]
}

export type DiffFinding = Finding & { path: string }

const unquote = (path: string): string => (path.startsWith('"') && path.endsWith('"') ? path.slice(1, -1) : path)

/** The added lines of a unified diff, grouped by file. */
export function addedLines(diff: string): AddedFile[] {
  const files = new Map<string, AddedFile>()
  let current: AddedFile | undefined
  let line = 0
  let isInHunk = false

  for (const row of diff.split('\n')) {
    if (row.startsWith('diff --git ')) {
      current = undefined
      isInHunk = false
      continue
    }
    if (!isInHunk && row.startsWith('+++ ')) {
      const target = unquote(row.slice(4).replace(/\t.*$/, ''))
      if (target === '/dev/null') {
        current = undefined
      } else {
        const path = target.startsWith('b/') ? target.slice(2) : target
        current = files.get(path) ?? { path, lines: [], numbers: [] }
        files.set(path, current)
      }
      continue
    }
    const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(row)
    if (hunk !== null) {
      line = Number(hunk[1])
      isInHunk = true
      continue
    }
    if (!isInHunk || current === undefined) continue
    if (row.startsWith('+')) {
      current.lines.push(row.slice(1))
      current.numbers.push(line++)
    } else if (row.startsWith(' ')) {
      line++
    }
  }
  return [...files.values()]
}

export type DiffScan = {
  findings: DiffFinding[]
  /** A file's added text was over 4 MiB and was not scanned. */
  isSkipped: boolean
}

/** Scans each file's added lines; a finding points at the real line in the file. */
export function scanDiff(diff: string, extraRules: readonly Rule[] = []): DiffScan {
  const findings: DiffFinding[] = []
  let isSkipped = false
  for (const file of addedLines(diff)) {
    if (file.lines.length === 0) continue
    const result = scanText(file.lines.join('\n'), { path: file.path, extraRules })
    if (result.isSkipped) {
      isSkipped = true
      continue
    }
    for (const finding of result.findings) {
      findings.push({ ...finding, line: file.numbers[finding.line - 1] ?? finding.line, path: file.path })
    }
  }
  return { findings, isSkipped }
}

files.hooks/mask.ts:
// Masking and fingerprints. Pure: no `$`.
//
// This is the only place a Finding's `value` is read. What leaves it is a
// MaskedFinding: the type, the location, a masked preview and a fingerprint.
// That is all `$.state`, `$.store`, the interface and the messages to Claude
// may ever hold.

import type { Finding } from './detect.ts'

export type MaskedFinding = Omit<Finding, 'value' | 'start' | 'end'> & {
  /** `sk-ant-••••••3fA`, or `••••••` when the value has no safe part to show. */
  masked: string
  /** `sha256:` and 16 hex characters of the value's SHA-256. */
  fingerprint: string
}

const DOTS = '••••••'
/** Below this many characters after the prefix, the tail would give too much away. */
const MIN_TAIL_BODY = 16

/**
 * Identifying prefix and the last three characters. A value with no known
 * prefix shows nothing: the type already says what it is.
 */
export function mask(value: string, prefix?: string): string {
  if (prefix === undefined || !value.startsWith(prefix)) return DOTS
  const body = value.length - prefix.length
  return body >= MIN_TAIL_BODY ? `${prefix}${DOTS}${value.slice(-3)}` : `${prefix}${DOTS}`
}

/** `sha256:` plus the first 8 bytes of the digest, in hex. */
export async function fingerprint(value: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value))
  const hex = Array.from(new Uint8Array(digest).slice(0, 8), (byte) => byte.toString(16).padStart(2, '0')).join('')
  return `sha256:${hex}`
}

/** The finding without its value: the only form that may be kept or shown. */
export async function describe(finding: Finding): Promise<MaskedFinding> {
  const { value, start: _start, end: _end, ...rest } = finding
  return { ...rest, masked: mask(value, finding.prefix), fingerprint: await fingerprint(value) }
}

/**
 * `text` with each finding's value replaced by its masked form. The findings must come
 * from scanning this same `text`; overlapping ones keep the first replacement.
 */
export function redact(text: string, findings: readonly Finding[]): string {
  let out = text
  let limit = Number.POSITIVE_INFINITY
  for (const finding of [...findings].sort((a, b) => b.start - a.start)) {
    if (finding.end > limit) continue
    out = out.slice(0, finding.start) + mask(finding.value, finding.prefix) + out.slice(finding.end)
    limit = finding.start
  }
  return out
}

files.hooks/messages.ts:
// What LeakStop says: the hold question and the denial message. Pure: no `$`.
//
// Everything here is built from a MaskedFinding, so no complete secret can
// reach the interface or the model. The most that appears is the rule's
// identifying prefix and the last three characters.

import { classifyPath } from './detect.ts'
import type { MaskedFinding } from './mask.ts'
import { destinationOf, toolLabel } from './outbound.ts'

/** The labels of the options in the dialogs. */
export const USE_ENV = 'Use environment variable'
export const ALLOW_ONCE = 'Allow once'
export const CANCEL = 'Cancel'
export const SHOW_NAMES = 'Show names only'
export const ADD_GITIGNORE = 'Add to .gitignore'

const MAX_FREE_TEXT = 200

/**
 * What the model reads before a denial: who decided, so it neither retries after a cancel nor asks the user
 * again after a choice that already told it what to do. `answer` is `undefined` when nobody could answer.
 */
export function answerNote(answer: string | undefined): string {
  switch (answer) {
    case undefined:
      return 'LeakStop could not ask the user, so the action was denied.'
    case CANCEL:
      return 'The user chose Cancel: do not retry this action or work around it. Ask them how they want to proceed.'
    case USE_ENV:
      return 'The user chose "Use environment variable": do that now instead of writing the value.'
    case ADD_GITIGNORE:
      return 'The user chose "Add to .gitignore": add those files to .gitignore now, then retry.'
    default: {
      const text = answer.replace(/\s+/g, ' ').trim()
      const shown = text.length > MAX_FREE_TEXT ? `${text.slice(0, MAX_FREE_TEXT)}…` : text
      return `The user picked no option and answered: "${shown}". That is not an approval of the original action; follow what they said, and ask them if it is unclear.`
    }
  }
}

/**
 * The question as one line, for a surface that does not keep line breaks (the VS Code panel runs them
 * together into one paragraph): the lines read in order, set apart by dashes.
 */
export function flatten(question: string): string {
  return question
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line !== '')
    .join(' — ')
}

/** The tools whose write is checked. */
export type WriteTool = 'Write' | 'Edit' | 'NotebookEdit'

const VERB: Record<WriteTool, string> = { Write: 'write', Edit: 'edit', NotebookEdit: 'notebook edit' }

/** The variable a secret of each kind belongs in. */
const ENV_VARS: Record<string, string> = {
  'aws-access-key': 'AWS_ACCESS_KEY_ID',
  'github-token': 'GITHUB_TOKEN',
  'github-fine-grained-token': 'GITHUB_TOKEN',
  'gitlab-token': 'GITLAB_TOKEN',
  'anthropic-key': 'ANTHROPIC_API_KEY',
  'openai-key': 'OPENAI_API_KEY',
  'stripe-live-key': 'STRIPE_SECRET_KEY',
  'stripe-test-key': 'STRIPE_SECRET_KEY',
  'slack-token': 'SLACK_BOT_TOKEN',
  'google-api-key': 'GOOGLE_API_KEY',
  'npm-token': 'NPM_TOKEN',
  'npmrc-auth-token': 'NPM_TOKEN',
  'huggingface-token': 'HF_TOKEN',
  'pypirc-password': 'PYPI_TOKEN',
  'url-credentials': 'DATABASE_URL',
  'jwt': 'AUTH_TOKEN',
}

/** `src/config.ts` for `/work/app/src/config.ts` when the session runs in `/work/app`. */
export function displayPath(path: string, cwd?: string): string {
  if (cwd === undefined || cwd === '') return path
  const root = cwd.endsWith('/') ? cwd : `${cwd}/`
  return path.startsWith(root) ? path.slice(root.length) : path
}

const article = (label: string): string => (/^(?:[aeiou]|npm|AWS|SSH)/i.test(label) ? 'an' : 'a')

const typeOf = (finding: MaskedFinding): string => `${article(finding.label)} ${finding.label}`

/** `sk-ant-…`, or nothing when the rule has no public prefix. */
const hint = (finding: MaskedFinding): string => (finding.prefix === undefined ? '' : ` (${finding.prefix}…)`)

function advice(path: string, findings: readonly MaskedFinding[]): string {
  if (classifyPath(path)?.kind === 'env') {
    return 'This file is not ignored by git: add it to .gitignore first, then write the secret there.'
  }
  const first = findings[0]
  if (first?.ruleId === 'private-key') {
    return 'Keep the key out of the repository: store it outside the project or in a secret manager, and read its path from an environment variable.'
  }
  const name = first === undefined ? undefined : ENV_VARS[first.ruleId]
  if (name === undefined) {
    return 'Read the value from an environment variable instead, add it to .env (ignored by git) and declare the variable without a value in .env.example.'
  }
  return `Read the value from the environment variable ${name} instead (for example process.env.${name}), add it to .env (ignored by git) and declare the variable without a value in .env.example.`
}

/** The message Claude reads when a write is denied: type, location and alternative, never the value. */
export function denyMessage(tool: WriteTool, path: string, findings: readonly MaskedFinding[]): string {
  const shown = findings.slice(0, 5)
  const what = shown.map((f) => `${path}:${f.line} contains ${typeOf(f)}${hint(f)}`).join('; ')
  const more = findings.length > shown.length ? ` (and ${findings.length - shown.length} more)` : ''
  return `LeakStop blocked this ${VERB[tool]}: ${what}${more}. ${advice(path, findings)}`
}

/** The hold question: plain text, because the dialog supports no colors. */
export function holdQuestion(tool: WriteTool, path: string, findings: readonly MaskedFinding[]): string {
  const severity = findings.some((f) => f.severity === 'critical') ? 'CRITICAL' : 'MEDIUM'
  const shown = findings.slice(0, 3)
  const lines = [`LeakStop · ${severity}`]
  for (const finding of shown) {
    lines.push(`${finding.label} in ${tool} → ${path}:${finding.line}`, `  ${finding.masked}`)
  }
  if (findings.length > shown.length) lines.push(`  …and ${findings.length - shown.length} more`)
  lines.push(
    classifyPath(path)?.kind === 'env'
      ? 'This file is not ignored by git and would end up in the repository.'
      : 'This file is not ignored by git, so the secret would end up in the repository.',
    '',
    'How do you want to handle it?',
  )
  return lines.join('\n')
}

/** The question for an edit of LeakStop's own configuration. */
export function configQuestion(path: string): string {
  return [
    'LeakStop · CONFIGURATION',
    `Claude wants to change ${path}`,
    "This file can relax LeakStop's rules, so only you should approve it.",
    '',
    'Allow this change?',
  ].join('\n')
}

export function configDenyMessage(path: string): string {
  return `LeakStop blocked this change: ${path} controls LeakStop's own rules and can only be changed with the user's approval. Ask the user to edit it.`
}

/** One transcript line for a finding that warns instead of holding. */
export function warnLine(path: string, finding: MaskedFinding, wouldHold: boolean): string {
  const tail = wouldHold ? ' · monitor mode: this would have been held' : ''
  return `LeakStop · ${finding.severity.toUpperCase()} · ${finding.label} in ${path}:${finding.line}${tail}`
}

// --- Bash and Read ------------------------------------------------------------

const list = (items: readonly string[], max = 5): string => {
  const shown = items.slice(0, max).join(', ')
  return items.length > max ? `${shown} and ${items.length - max} more` : shown
}

/** What the model reads when a command with a literal secret is denied. */
export function commandSecretDeny(findings: readonly MaskedFinding[]): string {
  const what = findings.slice(0, 5).map((f) => `${typeOf(f)}${hint(f)}`).join(', ')
  const name = findings[0] === undefined ? undefined : ENV_VARS[findings[0].ruleId]
  const variable = name === undefined ? 'an environment variable' : `an environment variable (for example ${name})`
  const use = name === undefined ? 'a variable' : `$${name}`
  return `LeakStop blocked this command: it contains ${what}. Keep the value in ${variable}, defined in .env (ignored by git), and refer to it as ${use} instead of writing it out.`
}

export function commandSecretQuestion(findings: readonly MaskedFinding[]): string {
  const severity = findings.some((f) => f.severity === 'critical') ? 'CRITICAL' : 'MEDIUM'
  const lines = [`LeakStop · ${severity}`]
  for (const finding of findings.slice(0, 3)) lines.push(`${finding.label} in the Bash command`, `  ${finding.masked}`)
  if (findings.length > 3) lines.push(`  …and ${findings.length - 3} more`)
  lines.push('Written out in a command, the secret stays in the session history.', '', 'How do you want to handle it?')
  return lines.join('\n')
}

/** Printing sensitive files or the environment: the values would enter the conversation. */
export function dumpQuestion(subject: string, items: readonly string[]): string {
  return [
    'LeakStop · CRITICAL',
    subject,
    `  ${list(items)}`,
    "The values would enter the model's context and the session history.",
    '',
    'How do you want to handle it?',
  ].join('\n')
}

export function fileReadDeny(files: readonly string[]): string {
  return `LeakStop blocked this command: it would print ${list(files)} into the conversation, where the values would stay in the model's context and the session history. Do not read the file. To see which variables exist, read .env.example or ask the user. To add a variable without reading the file, append it: echo 'NAME=value' >> .env`
}

export const ENV_DUMP_DENY =
  'LeakStop blocked this command: printing the whole environment would put secret values into the conversation. Ask for the specific variable you need, or list names only with: env | cut -d= -f1'

export function secretVarDeny(names: readonly string[]): string {
  return `LeakStop blocked this command: it would print the value of ${list(names)} into the conversation. Use the variable without printing it (for example by passing it to the program that needs it), or ask the user.`
}

export function gitAddQuestion(files: readonly string[]): string {
  return [
    'LeakStop · CRITICAL',
    'git add would stage files that hold secrets and are not ignored by git',
    `  ${list(files)}`,
    'They would end up in the next commit.',
    '',
    'How do you want to handle it?',
  ].join('\n')
}

export function gitAddDeny(files: readonly string[]): string {
  return `LeakStop blocked git add: ${list(files)} hold secrets and are not ignored by git. Add them to .gitignore (and run git rm --cached on any that are already tracked), then retry. Stage specific files instead of -A or . while sensitive files are not ignored.`
}

/** A commit or push that would publish a secret. The fingerprint lets the user allow that one finding. */
export function gitBlockMessage(operation: 'commit' | 'push', findings: readonly (MaskedFinding & { path: string })[]): string {
  const what = findings.slice(0, 5).map((f) => `${typeOf(f)}${hint(f)} at ${f.path}:${f.line}`).join('; ')
  const more = findings.length > 5 ? ` (and ${findings.length - 5} more)` : ''
  const subject = operation === 'commit' ? 'the staged changes add' : 'the commits to be pushed add'
  const fix =
    operation === 'commit'
      ? 'Unstage the file (git restore --staged <file>), read the value from an environment variable instead and commit again.'
      : 'Remove the secret from those commits before pushing, read it from an environment variable instead, and rotate it if it was ever shared.'
  const allow = findings.slice(0, 3).map((f) => f.fingerprint).join(' ')
  return `LeakStop blocked this git ${operation}: ${subject} ${what}${more}. ${fix} If the user wants it anyway, they can run /leakstop allow ${allow}`
}

export function readQuestion(path: string): string {
  return ['LeakStop · CRITICAL', 'Read of a sensitive file', `  ${path}`, "Its contents would enter the model's context and the session history.", '', 'How do you want to handle it?'].join('\n')
}

export function readDeny(path: string, isStrict: boolean): string {
  const never = isStrict ? ' Strict mode never allows reading sensitive files.' : ''
  return `LeakStop blocked reading ${path}: it holds secrets that would enter the conversation.${never} Do not read it; read .env.example for variable names or ask the user. To add a variable without reading the file, append it: echo 'NAME=value' >> .env`
}

/** The transcript line for something that warns instead of holding. */
export function noticeLine(what: string, isMonitor: boolean): string {
  return `LeakStop · ${what}${isMonitor ? ' · monitor mode: this would have been held' : ''}`
}

/** A recursive search that would print lines of sensitive files nobody named. */
export function searchQuestion(files: readonly string[]): string {
  return dumpQuestion('This search would print lines from files that hold secrets', files)
}

export function searchDeny(files: readonly string[]): string {
  return `LeakStop blocked this search: it would print lines from ${list(files)}, which hold secrets, into the conversation. Search specific folders such as src/ instead, or exclude those files (for example grep -r --exclude='.env*' …, or rg -g '!.env*'). To list only the files that match, use grep -rl or rg -l.`
}

// --- Outbound tools ------------------------------------------------------------

type Located = MaskedFinding & { path: string }

/** What the model reads when a call that sends something away is denied: where the secret is and what to do instead. */
export function outboundDeny(tool: string, findings: readonly Located[]): string {
  const what = findings.slice(0, 5).map((f) => `${f.path} contains ${typeOf(f)}${hint(f)}`).join('; ')
  const more = findings.length > 5 ? ` (and ${findings.length - 5} more)` : ''
  return `LeakStop blocked this ${toolLabel(tool)} call: ${what}${more}. It would be sent ${destinationOf(tool)}, and a credential that leaves the session cannot be taken back. Leave the value out: describe what is needed, or name the environment variable that holds it, and send that instead.`
}

export function outboundQuestion(tool: string, findings: readonly Located[]): string {
  const severity = findings.some((f) => f.severity === 'critical') ? 'CRITICAL' : 'MEDIUM'
  const lines = [`LeakStop · ${severity}`]
  // The tool is already named: "in Agent → prompt", not "in Agent → Agent › prompt".
  const own = `${toolLabel(tool)} › `
  for (const finding of findings.slice(0, 3)) lines.push(`${finding.label} in ${toolLabel(tool)} → ${finding.path.startsWith(own) ? finding.path.slice(own.length) : finding.path}`, `  ${finding.masked}`)
  if (findings.length > 3) lines.push(`  …and ${findings.length - 3} more`)
  lines.push(`This call would send it ${destinationOf(tool)}.`, '', 'How do you want to handle it?')
  return lines.join('\n')
}

/** A file that holds secrets named in a call that sends it away. */
export function outboundFileQuestion(tool: string, files: readonly string[]): string {
  return ['LeakStop · CRITICAL', `${toolLabel(tool)} would send files that hold secrets`, `  ${list(files)}`, `Their contents would go ${destinationOf(tool)}.`, '', 'How do you want to handle it?'].join('\n')
}

export function outboundFileDeny(tool: string, files: readonly string[]): string {
  return `LeakStop blocked this ${toolLabel(tool)} call: ${list(files)} hold secrets and would be sent ${destinationOf(tool)}. Do not send them. Send a copy without the secrets (for example .env.example with the values removed), or ask the user.`
}

// --- Tool output -----------------------------------------------------------------

/** What the model reads after an output in which LeakStop masked secrets. */
export function maskedContext(tool: string, findings: readonly MaskedFinding[]): string {
  const what = findings.slice(0, 5).map(typeOf).join(', ')
  const more = findings.length > 5 ? ` (and ${findings.length - 5} more)` : ''
  return `LeakStop masked ${what}${more} in the output of this ${tool} call: the value never reached you and is not in the transcript. Do not try to print or read it another way; if the task needs it, use it from an environment variable or ask the user.`
}

/** The line above the prompt when an output carried a secret. */
export function maskedLine(tool: string, finding: MaskedFinding, isMonitor: boolean): string {
  return `LeakStop · ${finding.severity.toUpperCase()} · ${finding.label} in the output of ${tool}${isMonitor ? ' · monitor mode: this would have been masked' : ' · masked'}`
}

/** Instead of an output LeakStop could not check after the tool ran. */
export const OUTPUT_FAILURE = 'LeakStop could not check the output of this call, so it was withheld. The call did run; do not run it again just to see its output.'

/** What the model reads after a message in which LeakStop masked a pasted secret. */
export function promptMaskedContext(findings: readonly MaskedFinding[]): string {
  const what = findings.slice(0, 5).map(typeOf).join(', ')
  return `LeakStop masked ${what} that the user pasted into this message: the value never reached you. If the task needs it, ask the user to put it in an environment variable or a git-ignored file instead of the chat.`
}

/** Denial of a Write that would put the masked form of a secret over the real value on disk. */
export function maskedOverwriteDeny(path: string, findings: readonly MaskedFinding[]): string {
  const what = findings.slice(0, 5).map((f) => `${typeOf(f)} (${f.masked})`).join(', ')
  return `LeakStop blocked this write: ${path} holds ${what}, and what you would write has only the masked form LeakStop showed you, so the real value would be lost. Change the file with Edit around that line instead, without including the masked value in old_string or new_string.`
}

files.hooks/outbound.ts:
// What a tool call sends out of the session: to the web, to another agent or
// session, into a published page or to an MCP server. Pure: no `$`, no I/O.
//
// Everything a call carries as text is collected (the model chooses the field
// names of an MCP tool, so there is no list to keep), and the fields that name
// local files whose contents travel with the call are listed apart so the hook
// can read them.

/** The built-in tools that send what they are given to somewhere else. MCP tools are matched by their `mcp__` prefix. */
export const OUTBOUND_TOOLS = ['WebFetch', 'WebSearch', 'Agent', 'SendMessage', 'SendFile', 'Artifact', 'ArtifactData', 'ArtifactComments', 'PushNotification', 'SendFeedback', 'RemoteTrigger'] as const

/** Keys the engine puts beside a tool's own arguments. */
const RESERVED = new Set(['tool', 'tool_use_id', 'agentId'])

const MAX_PARTS = 200
/** Text past MAX_PARTS is scanned as one block, up to this many characters. */
const MAX_OVERFLOW = 1024 * 1024
const MAX_DEPTH = 6
/** Files whose paths are checked; only the first MAX_READ of them are opened. */
const MAX_FILES = 200
export const MAX_READ = 20
/** Keys shorter than this cannot be a provider token by themselves. */
const MIN_KEY = 16

/** A piece of text the call carries, and the argument it came from (`prompt`, `batch[0].payload`). */
export type Part = { field: string; text: string }

export type Outbound = {
  texts: Part[]
  /** Local files whose contents the call sends, as the paths it names. */
  files: string[]
  /** More text or more files than are looked at; the rest was not read. */
  isTruncated: boolean
}

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null && !Array.isArray(value)

/** Arguments that name files the tool reads and sends. */
function filesNamed(input: Record<string, unknown>): string[] {
  const files: string[] = []
  const add = (value: unknown): void => {
    if (typeof value === 'string' && value !== '') files.push(value)
  }
  const addAll = (value: unknown): void => {
    if (Array.isArray(value)) value.forEach(add)
  }
  switch (input.tool) {
    case 'SendFile':
      addAll(input.files)
      break
    case 'Artifact': {
      add(input.file_path)
      addAll(input.file_paths)
      // `files` is a list of { path } or a map from published path to a source path or { from }.
      if (Array.isArray(input.files)) for (const item of input.files) add(isRecord(item) ? item.path : undefined)
      else if (isRecord(input.files)) for (const source of Object.values(input.files)) add(isRecord(source) ? source.from : source)
      break
    }
    case 'ArtifactData':
      add(input.file_path)
      if (Array.isArray(input.writes)) for (const write of input.writes) add(isRecord(write) ? write.file_path : undefined)
      break
  }
  return [...new Set(files)]
}

/** The text of a call and the files it sends. Nothing is dropped: past the limits the rest is folded into one block. */
export function collect(input: Record<string, unknown>): Outbound {
  const texts: Part[] = []
  let overflow = ''
  let isTruncated = false
  const add = (field: string, text: string): void => {
    if (texts.length < MAX_PARTS) {
      texts.push({ field, text })
    } else if (overflow.length + text.length + 1 <= MAX_OVERFLOW) {
      overflow += overflow === '' ? text : `\n${text}`
    } else {
      isTruncated = true
    }
  }
  const walk = (value: unknown, field: string, depth: number): void => {
    if (typeof value === 'string') {
      if (value !== '') add(field, value)
    } else if (value === null || typeof value !== 'object') {
      return
    } else if (depth >= MAX_DEPTH) {
      // Too deep to follow: its text is scanned as it is serialized.
      try {
        add(field, JSON.stringify(value))
      } catch {
        isTruncated = true
      }
    } else if (Array.isArray(value)) {
      value.forEach((item, index) => walk(item, `${field}[${index}]`, depth + 1))
    } else {
      // A key can hold a secret too (a map keyed by token), so the long ones are scanned, as one block.
      const keys = Object.keys(value).filter((key) => key.length >= MIN_KEY)
      if (keys.length > 0) add(`${field} (names)`, keys.join('\n'))
      for (const [key, item] of Object.entries(value)) walk(item, `${field}.${key}`, depth + 1)
    }
  }
  for (const [key, value] of Object.entries(input)) if (!RESERVED.has(key)) walk(value, key, 0)
  if (overflow !== '') texts.push({ field: '(further arguments)', text: overflow })

  const named = filesNamed(input)
  return { texts, files: named.slice(0, MAX_FILES), isTruncated: isTruncated || named.length > MAX_FILES }
}

/** Files that cannot hold a readable secret: reading them as text only costs time. */
export const isLikelyBinary = (path: string): boolean => /\.(?:png|jpe?g|gif|webp|avif|ico|bmp|tiff?|pdf|woff2?|ttf|otf|eot|mp[34]|m4a|mov|webm|wav|ogg|zip|gz|tgz|bz2|xz|7z|rar|wasm|bin|exe|dylib|so|class|jar|sqlite3?)$/i.test(path)

const MCP_NAME = /^mcp__(.+?)__(.+)$/

/** `mcp__srv__tool` as `MCP srv/tool`; a built-in tool is its own name. */
export function toolLabel(tool: string): string {
  const match = MCP_NAME.exec(tool)
  return match === null ? tool : `MCP ${match[1]}/${match[2]}`
}

/** True for a tool whose arguments LeakStop reads as outbound. */
export const isOutbound = (tool: string): boolean => tool.startsWith('mcp__') || (OUTBOUND_TOOLS as readonly string[]).includes(tool)

/** Where what the call carries ends up, in words. */
export function destinationOf(tool: string): string {
  switch (tool) {
    case 'WebFetch':
      return 'to the web server it fetches, which can log it'
    case 'WebSearch':
      return 'to a search engine'
    case 'Agent':
      return "into another agent's context"
    case 'SendMessage':
      return 'to another agent or session'
    case 'SendFile':
      return 'to another session'
    case 'Artifact':
    case 'ArtifactData':
    case 'ArtifactComments':
      return 'into a page or database on claude.ai that other people may open'
    case 'PushNotification':
      return "to the user's phone through a push service"
    case 'SendFeedback':
      return 'to Anthropic'
    case 'RemoteTrigger':
      return 'to a remote trigger'
    default:
      return MCP_NAME.test(tool) ? `to the MCP server ${MCP_NAME.exec(tool)?.[1] ?? ''}` : 'outside the session'
  }
}

files.hooks/policy.ts:
// Policy: severity × destination × mode → action. Pure: no `$`.

import type { Severity } from './rules.ts'

export type Mode = 'monitor' | 'standard' | 'strict'

/** Pass: let it through. Warn: let it through and tell the user. Hold: ask. Block: deny without asking. */
export type Action = 'pass' | 'warn' | 'hold' | 'block'

/** Where the secret, or the sensitive thing, is about to go. */
export type Destination =
  | 'file' // Write/Edit to a path git does not ignore
  | 'ignored-file' // Write/Edit to a path git ignores, like a .env
  | 'command' // a literal secret inside a Bash command
  | 'outbound' // a secret in what a tool sends away: the web, another agent, a published page, an MCP server
  | 'sensitive-dump' // cat/head/less of a sensitive file, printenv, env
  | 'git-add' // git add -A or . with unignored sensitive files
  | 'git-commit' // secrets in what is staged
  | 'git-push' // secrets in the commits about to be pushed
  | 'read' // the Read tool on a sensitive file
  | 'config-edit' // Claude editing .leakstop.json
  | 'prompt' // a secret pasted by the user

const ORDER: readonly Action[] = ['pass', 'warn', 'hold', 'block']

/** The stronger of two actions. */
export function maxAction(a: Action, b: Action): Action {
  return ORDER.indexOf(a) >= ORDER.indexOf(b) ? a : b
}

/** The action for one finding, or one sensitive operation (pass `'critical'` for those). */
export function decide(destination: Destination, severity: Severity, mode: Mode): Action {
  if (destination === 'ignored-file') return 'pass'
  if (mode === 'monitor') return 'warn'
  if (destination === 'prompt') return 'warn'

  switch (destination) {
    case 'sensitive-dump':
    case 'git-add':
    case 'config-edit':
      return 'hold'
    case 'read':
      return mode === 'strict' ? 'block' : 'hold'
    case 'git-commit':
    case 'git-push':
      if (severity === 'critical') return 'block'
      return mode === 'strict' ? 'block' : 'warn'
    case 'file':
    case 'command':
    case 'outbound':
      if (severity === 'critical') return 'hold'
      return mode === 'strict' ? 'hold' : 'warn'
  }
}

/** The strongest action over several findings; `pass` when there are none. */
export function decideAll(destination: Destination, severities: readonly Severity[], mode: Mode): Action {
  return severities.reduce<Action>((acc, severity) => maxAction(acc, decide(destination, severity, mode)), 'pass')
}

files.hooks/ui.ts:
// What the banner, the history panel and the `/leakstop` command say. Pure: no `$`.
//
// Strings are fitted to the width the surface gives (`bodyColumns`), so nothing
// here depends on the terminal's own size.

import type { StoredFinding } from '../types'
import { toolLabel } from './outbound.ts'

/** `…` when a line is cut. */
export function fit(text: string, width: number): string {
  if (width <= 0) return ''
  return text.length <= width ? text : `${text.slice(0, Math.max(0, width - 1))}…`
}

/** `HH:MM` in the user's time zone. */
export function formatTime(at: number): string {
  const date = new Date(at)
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`
}

const SEVERITY = { critical: 'CRITICAL', medium: 'MEDIUM' } as const

/** Where it happened: a file and line, or the command. */
export function where(finding: StoredFinding): string {
  if (finding.path === '') return finding.tool === 'Bash' ? 'Bash command' : `${toolLabel(finding.tool)} call`
  return finding.line > 0 ? `${finding.path}:${finding.line}` : finding.path
}

/** What happened to it, in words. */
export function outcome(finding: StoredFinding): string {
  switch (finding.decision) {
    case 'allowed':
      return 'allowed'
    case 'denied':
      return 'denied'
    case 'warned':
      return finding.severity === 'critical' ? 'logged, not enforced' : 'warned'
    case 'passed':
      return 'passed (git ignores this file)'
    case 'masked':
      return finding.tool === 'prompt' ? 'masked before it was sent' : 'masked in the output'
  }
}

/**
 * The one line above the prompt. `width` is the room the band has: the first
 * row is two cells shorter, because the terminal draws the pane's closing mark over it.
 */
export function bannerLine(banner: readonly StoredFinding[], paused: boolean, width: number): string {
  const room = Math.max(0, width - 2)
  if (paused) return fit('△ LeakStop · PAUSED · nothing is being checked · /leakstop resume', room)
  const latest = banner[banner.length - 1]
  if (latest === undefined) return ''
  const more = banner.length > 1 ? ` (+${banner.length - 1} more)` : ''
  const head = `△ LeakStop · ${SEVERITY[latest.severity]} · ${latest.label} in ${where(latest)}${more}`
  const tail = ` · ${latest.decision === 'masked' ? 'masked' : latest.severity === 'critical' ? 'logged' : 'warned'} · /leakstop`
  return room < tail.length + 12 ? fit(`${head}${tail}`, room) : `${fit(head, room - tail.length)}${tail}`
}

export type HistoryRow = { head: string; detail: string }

/** The history, newest first, numbered as `/leakstop allow <number>` counts them. */
export function historyRows(findings: readonly StoredFinding[], width: number): HistoryRow[] {
  return findings
    .map((finding, index): HistoryRow => ({
      head: fit(`#${index + 1} ${formatTime(finding.at)} ${SEVERITY[finding.severity].padEnd(8)} ${finding.label} · ${where(finding)}`, width),
      detail: fit(`   → ${outcome(finding)}`, width),
    }))
    .reverse()
}

const MAX_TEXT_ROWS = 15

/** The same history as plain text, for where no panel can be drawn. */
export function summaryText(findings: readonly StoredFinding[], paused: boolean, warnings: readonly string[] = []): string {
  const state = paused ? ' · PAUSED (nothing is being checked)' : ''
  const notes = warnings.slice(0, 5).map((warning) => `.leakstop.json: ${warning}`)
  if (findings.length === 0) return [`LeakStop · no findings this session${state}`, ...notes].join('\n')
  const rows = historyRows(findings, 200).slice(0, MAX_TEXT_ROWS)
  const lines = rows.map((row) => `${row.head} ${row.detail.trim()}`)
  const hidden = findings.length - rows.length
  return [
    `LeakStop · ${findings.length} finding${findings.length === 1 ? '' : 's'} this session${state}`,
    ...lines,
    ...(hidden > 0 ? [`…and ${hidden} older`] : []),
    ...notes,
    'Allow one for good with /leakstop allow <number or sha256:…>',
  ].join('\n')
}

/** Where a fingerprint was allowed. */
export type AllowSource = 'session' | 'forever' | 'project'

const SOURCE_TEXT: Record<AllowSource, string> = { session: 'this session', forever: 'for good', project: '.leakstop.json' }

export type Allowed = { fingerprint: string; sources: AllowSource[] }

/** Every fingerprint that is allowed, with where each came from, in a stable order. */
export function mergeAllowed(session: readonly string[], forever: readonly string[], project: readonly string[]): Allowed[] {
  const merged = new Map<string, Set<AllowSource>>()
  const add = (source: AllowSource, fingerprints: readonly string[]): void => {
    for (const fingerprint of fingerprints) merged.set(fingerprint, (merged.get(fingerprint) ?? new Set()).add(source))
  }
  add('forever', forever)
  add('session', session)
  add('project', project)
  return [...merged].map(([fingerprint, sources]) => ({ fingerprint, sources: [...sources] }))
}

const MAX_ALLOWED_ROWS = 25

/** What is allowed, with what the history knows about each finding (a type and a place, never a value). */
export function allowedText(allowed: readonly Allowed[], findings: readonly StoredFinding[]): string {
  if (allowed.length === 0) return 'LeakStop · nothing is allowed: every finding is checked'
  const known = new Map<string, StoredFinding>()
  for (const finding of findings) known.set(finding.fingerprint, finding)
  const rows = allowed.slice(0, MAX_ALLOWED_ROWS).map(({ fingerprint, sources }) => {
    const finding = known.get(fingerprint)
    const what = finding === undefined ? '' : ` · ${finding.label} · ${where(finding)}`
    return `  ${fingerprint} · ${sources.map((source) => SOURCE_TEXT[source]).join(' + ')}${what}`
  })
  const hidden = allowed.length - rows.length
  return [
    `LeakStop · ${allowed.length} allowed`,
    ...rows,
    ...(hidden > 0 ? [`…and ${hidden} more`] : []),
    'Stop allowing one with /leakstop forget <fingerprint>, or everything of yours with /leakstop forget all.',
    ...(allowed.some((a) => a.sources.includes('project')) ? ['Fingerprints from .leakstop.json are removed by editing that file.'] : []),
  ].join('\n')
}

export type CommandArgs =
  | { kind: 'open' }
  | { kind: 'pause' }
  | { kind: 'resume' }
  | { kind: 'allow'; ids: string[] }
  | { kind: 'allowed' }
  | { kind: 'forget'; ids: string[] }
  | { kind: 'reload' }
  | { kind: 'usage' }

export function parseArgs(args: string): CommandArgs {
  const words = args.trim().split(/\s+/).filter((word) => word !== '')
  const [first, ...rest] = words
  if (first === undefined) return { kind: 'open' }
  if (first === 'pause' && rest.length === 0) return { kind: 'pause' }
  if (first === 'resume' && rest.length === 0) return { kind: 'resume' }
  if (first === 'allow' && rest.length > 0) return { kind: 'allow', ids: rest }
  if ((first === 'allowed' || first === 'list') && rest.length === 0) return { kind: 'allowed' }
  if (first === 'forget' && rest.length > 0) return { kind: 'forget', ids: rest }
  if (first === 'reload' && rest.length === 0) return { kind: 'reload' }
  return { kind: 'usage' }
}

export const USAGE = [
  'Usage:',
  '  /leakstop                 show this session’s findings',
  '  /leakstop pause           stop checking until you resume',
  '  /leakstop resume          start checking again',
  '  /leakstop allow <id>...   allow findings for good: a number from the history or a sha256:… fingerprint',
  '  /leakstop allowed         list what is allowed: for this session, for good, and by .leakstop.json',
  '  /leakstop forget <id>...  stop allowing findings: a history number or a sha256:… fingerprint',
  '  /leakstop forget all      stop allowing everything you allowed (what .leakstop.json allows stays)',
  '  /leakstop reload          read .leakstop.json again',
].join('\n')

const FINGERPRINT = /^(?:sha256:)?([0-9a-f]{16})$/

/** Turns what the user typed into fingerprints; `unknown` lists what matched nothing. */
export function resolveIds(ids: readonly string[], findings: readonly StoredFinding[]): { fingerprints: string[]; unknown: string[] } {
  const fingerprints: string[] = []
  const unknown: string[] = []
  for (const id of ids) {
    const number = /^#?(\d+)$/.exec(id)
    const hex = FINGERPRINT.exec(id.toLowerCase())
    const byNumber = number === null ? undefined : findings[Number(number[1]) - 1]
    if (byNumber !== undefined) fingerprints.push(byNumber.fingerprint)
    else if (hex !== null) fingerprints.push(`sha256:${hex[1]}`)
    else unknown.push(id)
  }
  return { fingerprints: [...new Set(fingerprints)], unknown }
}

files.hooks/rules.ts:
// The pattern catalog: data only, no `$` and no side effects.
//
// Every regex here is linear: quantifiers are bounded or run over a character
// class that cannot also match the next token, so a hostile input cannot make
// a scan blow up. A hook that runs out of time is skipped by Claude Code and
// the call would go on, so a slow regex is a security bug.

export type Severity = 'critical' | 'medium'

export type Rule = {
  id: string
  /** What the user reads: "Anthropic API key". */
  label: string
  severity: Severity
  /** Global regex. */
  regex: RegExp
  /** The capture groups that can hold the secret; the first one that matched wins. Absent: the whole match. */
  groups?: readonly number[]
  /** Fixed identifying prefix, the only part of the value masking may show. */
  prefix?: string
  /** Shannon entropy (bits per character) the value must reach. */
  minEntropy?: number
  /** Heuristic rule: false-positive exclusions apply and a provider finding on the same text wins. */
  isGeneric?: boolean
  /** A last, rule-specific check on the value. */
  accept?: (value: string, match: RegExpMatchArray) => boolean
}

const base64Length = (text: string): number => text.replace(/[^A-Za-z0-9+/=]/g, '').length

/** A private key header with a real body; a header alone is documentation or a regex. */
const hasKeyBody = (value: string): boolean =>
  base64Length(value.replace(/-----(?:BEGIN|END)[^-]*-----/g, '')) >= 40

export const RULES: readonly Rule[] = [
  {
    id: 'private-key',
    label: 'Private key',
    severity: 'critical',
    regex: /-----BEGIN (?:[A-Z]+ )*PRIVATE KEY(?: BLOCK)?-----[\s\S]{0,16384}?(?:-----END (?:[A-Z]+ )*PRIVATE KEY(?: BLOCK)?-----|$)/g,
    accept: hasKeyBody,
  },
  {
    id: 'aws-access-key',
    label: 'AWS access key ID',
    severity: 'critical',
    regex: /\b(?:AKIA|ASIA)[A-Z2-7]{16}\b/g,
    prefix: 'AKIA',
  },
  {
    id: 'github-token',
    label: 'GitHub token',
    severity: 'critical',
    regex: /\bgh[pousr]_[A-Za-z0-9]{36,255}\b/g,
    prefix: 'ghp_',
  },
  {
    id: 'github-fine-grained-token',
    label: 'GitHub fine-grained token',
    severity: 'critical',
    regex: /\bgithub_pat_[A-Za-z0-9_]{36,255}\b/g,
    prefix: 'github_pat_',
  },
  {
    id: 'gitlab-token',
    label: 'GitLab token',
    severity: 'critical',
    regex: /\bglpat-[A-Za-z0-9_-]{20,}/g,
    prefix: 'glpat-',
  },
  {
    id: 'anthropic-key',
    label: 'Anthropic API key',
    severity: 'critical',
    regex: /\bsk-ant-[A-Za-z0-9_-]{20,}/g,
    prefix: 'sk-ant-',
  },
  {
    id: 'openai-key',
    label: 'OpenAI API key',
    severity: 'critical',
    regex: /\bsk-(?:proj|svcacct|admin)-[A-Za-z0-9_-]{20,}/g,
    prefix: 'sk-proj-',
  },
  {
    id: 'stripe-live-key',
    label: 'Stripe live key',
    severity: 'critical',
    regex: /\b[sr]k_live_[A-Za-z0-9]{16,}/g,
    prefix: 'sk_live_',
  },
  {
    id: 'stripe-test-key',
    label: 'Stripe test key',
    severity: 'medium',
    regex: /\b[sr]k_test_[A-Za-z0-9]{16,}/g,
    prefix: 'sk_test_',
  },
  {
    id: 'slack-token',
    label: 'Slack token',
    severity: 'critical',
    regex: /\bxox[baprs]-[A-Za-z0-9-]{10,}/g,
    prefix: 'xoxb-',
  },
  {
    id: 'google-api-key',
    label: 'Google API key',
    severity: 'critical',
    regex: /\bAIza[0-9A-Za-z_-]{35}/g,
    prefix: 'AIza',
  },
  {
    id: 'npm-token',
    label: 'npm token',
    severity: 'critical',
    regex: /\bnpm_[A-Za-z0-9]{36}\b/g,
    prefix: 'npm_',
  },
  {
    id: 'huggingface-token',
    label: 'Hugging Face token',
    severity: 'critical',
    regex: /\bhf_[A-Za-z0-9]{34,}/g,
    prefix: 'hf_',
  },
  {
    // scheme://user:password@host. The secret is the password (group 2).
    id: 'url-credentials',
    label: 'Credentials in a URL',
    severity: 'critical',
    regex: /\b[a-z][a-z0-9+.-]{1,20}:\/\/([^\s:@/'"<>]{0,100}):([^\s@/'"<>]{3,200})@[^\s'"<>/]{1,255}/gi,
    groups: [2],
    // `REDACTED://postgres:postgres@localhost` is a local default, not a secret.
    accept: (_value, match) => (match[1] ?? '').toLowerCase() !== (match[2] ?? '').toLowerCase(),
  },
  {
    id: 'jwt',
    label: 'JSON Web Token',
    severity: 'medium',
    regex: /\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g,
    prefix: 'eyJ',
  },
  {
    // curl -H "Authorization: Bearer <literal>". A variable (`$TOKEN`) never matches.
    id: 'authorization-header',
    label: 'Authorization header credential',
    severity: 'critical',
    regex: /\bAuthorization["']?\s*[:=]\s*["']?(?:Bearer|Basic|Token)\s+([A-Za-z0-9._~+/=-]{20,})/gi,
    groups: [1],
    minEntropy: 3,
  },
  {
    // A suspicious key name, a separator and a high-entropy value. The value is
    // quoted (groups 1 and 2) or bare (group 3, which must also contain a digit
    // so identifiers such as `getApiKeyFromConfig` do not count).
    id: 'generic-assignment',
    label: 'Hard-coded credential',
    severity: 'medium',
    regex:
      /(?:password|passwd|pwd|secret|api[_-]?key|apikey|access[_-]?key|auth[_-]?token|access[_-]?token|client[_-]?secret|private[_-]?key|token)[A-Za-z0-9_-]{0,20}["']?\s*[:=]>?\s*(?:"([^"\s]{16,200})"|'([^'\s]{16,200})'|([A-Za-z0-9_+/=.-]{20,200}))/gi,
    groups: [1, 2, 3],
    minEntropy: 3.5,
    isGeneric: true,
    accept: (value, match) => match[3] === undefined || /\d/.test(value),
  },
]

/** Rules that only make sense for one kind of file. */
export const NPMRC_RULES: readonly Rule[] = [
  {
    id: 'npmrc-auth-token',
    label: 'npm registry auth token',
    severity: 'critical',
    regex: /_authToken\s*=\s*([^\s$]{8,})/g,
    groups: [1],
  },
]

export const PYPIRC_RULES: readonly Rule[] = [
  {
    id: 'pypirc-password',
    label: 'PyPI password or token',
    severity: 'critical',
    regex: /^[ \t]*password[ \t]*[:=][ \t]*([^\s$]{6,})/gim,
